            ps4(3, 3, 2, 2, 4) = acc_ps4_q_1122
            ps4(2, 3, 3, 3, 4) = acc_ps4_q_1222
            ps4(3, 2, 3, 3, 4) = acc_ps4_q_1222
            ps4(3, 3, 2, 3, 4) = acc_ps4_q_1222
            ps4(3, 3, 3, 2, 4) = acc_ps4_q_1222
            ps4(3, 3, 3, 3, 4) = acc_ps4_q_2222
         end block
      end select

   end subroutine svdw_powersums

   !> Per-atom kind tensors of one active atom.
   !>
   !> Sets `at{n}(i1..in, kind)` = d^n/dr_i1..dr_in of `u_A**m`, where
   !> `u_A = exp(-(blend_k/3)*(||d_a|| - R_a))` and the kind slot selects the
   !> exponent: 1 -> m = 1, 2 -> m = 2, 3 -> m = 3, 4 -> m = 3/2.
   !>
   !> The caller runs this once per active atom and adds the results into the
   !> `ps*` accumulators; the same per-atom tensors are then reused by
   !> `svdw_nuclear_eval`, `svdw_pair_eval` and `svdw_hvp_eval`, so the
   !> exponential is evaluated exactly once per atom and per evaluation point.
   !>
   !> Nuclear derivatives never need a separate table: `u_A` depends on `r` and
   !> `R_A` only through `d_a = r - R_A`, hence `d/dR_A,b = -d/dr_b` and the
   !> nuclear index is just one more entry of the same tensor, with a sign.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    d_a          Displacement r - R_A of the active atom
   !> @param[in]    R_a          Radius of the active atom
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    max_deriv    Highest spatial-derivative order to set (0..4); a larger value is
   !>                            treated as 4
   !> @param[out]   at0          Order-0 kind tensor of this atom
   !> @param[out]   at1          Order-1 kind tensor of this atom
   !> @param[out]   at2          Order-2 kind tensor of this atom
   !> @param[out]   at3          Order-3 kind tensor of this atom
   !> @param[out]   at4          Order-4 kind tensor of this atom
   pure subroutine svdw_atom_eval(d_a, R_a, blend_k, max_deriv, at0, at1, at2, at3, at4)
      !> Displacement r - R_A of the active atom
      real(wp), intent(in) :: d_a(3)
      !> Radius of the active atom
      real(wp), intent(in) :: R_a
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> Highest spatial-derivative order to set (0..4); a larger value is treated as 4
      integer, intent(in) :: max_deriv
      !> Order-0 kind tensor of this atom
      real(wp), intent(out) :: at0(nkind)
      !> Order-1 kind tensor of this atom
      real(wp), intent(out) :: at1(3, nkind)
      !> Order-2 kind tensor of this atom
      real(wp), intent(out) :: at2(3, 3, nkind)
      !> Order-3 kind tensor of this atom
      real(wp), intent(out) :: at3(3, 3, 3, nkind)
      !> Order-4 kind tensor of this atom
      real(wp), intent(out) :: at4(3, 3, 3, 3, nkind)

      !> Distance ||d_a|| and screening factor u = exp(-(blend_k/3)*(x - R_a))
      real(wp) :: x, u

      x = sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3))
      u = exp(-blend_k/3.0_wp*(x - R_a))

      select case (max_deriv)
      case (0)
         block
            at0(1) = u
            at0(2) = (u*u)
            at0(3) = (u*u*u)
            at0(4) = (u*sqrt(u))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11

            cs0 = (u*u)
            cs1 = (u*u*u)
            cs2 = (u*sqrt(u))
            cs3 = blend_k/x
            cs4 = cs3*d_a(1)
            cs5 = (1.0_wp/3.0_wp)*u
            cs6 = cs3*cs5
            cs7 = (2.0_wp/3.0_wp)*cs0
            cs8 = cs3*cs7
            cs9 = cs1*cs3
            cs10 = (1.0_wp/2.0_wp)*cs2
            cs11 = cs10*cs3
            at0(1) = u
            at0(2) = cs0
            at0(3) = cs1
            at0(4) = cs2
            at1(1, 1) = -cs4*cs5
            at1(2, 1) = -cs6*d_a(2)
            at1(3, 1) = -cs6*d_a(3)
            at1(1, 2) = -cs4*cs7
            at1(2, 2) = -cs8*d_a(2)
            at1(3, 2) = -cs8*d_a(3)
            at1(1, 3) = -cs9*d_a(1)
            at1(2, 3) = -cs9*d_a(2)
            at1(3, 3) = -cs9*d_a(3)
            at1(1, 4) = -cs10*cs4
            at1(2, 4) = -cs11*d_a(2)
            at1(3, 4) = -cs11*d_a(3)
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, t_at2_p1_01, t_at2_p1_02, t_at2_p1_12, t_at2_p2_01, t_at2_p2_02
            real(wp) :: t_at2_p2_12, t_at2_p3_01, t_at2_p3_02, t_at2_p3_12, t_at2_q_01, t_at2_q_02
            real(wp) :: t_at2_q_12

            cs0 = (u*u)
            cs1 = (u*u*u)
            cs2 = (u*sqrt(u))
            cs3 = 1.0_wp/x
            cs4 = blend_k*cs3
            cs5 = cs4*d_a(1)
            cs6 = (1.0_wp/3.0_wp)*u
            cs7 = cs4*cs6
            cs8 = (2.0_wp/3.0_wp)*cs0
            cs9 = cs4*cs8
            cs10 = blend_k*cs1
            cs11 = cs10*cs3
            cs12 = (1.0_wp/2.0_wp)*cs2
            cs13 = cs12*cs4
            cs14 = (d_a(1)*d_a(1))
            cs15 = blend_k*x
            cs16 = (1.0_wp/3.0_wp)*cs15
            cs17 = -(x*x)
            cs18 = cs14 + cs17
            cs19 = 1.0_wp/(x*x*x)
            cs20 = blend_k*cs19
            cs21 = cs20*cs6
            cs22 = d_a(1)*d_a(2)
            cs23 = cs21*(cs16 + 1.0_wp)
            cs24 = cs23*d_a(3)
            cs25 = (d_a(2)*d_a(2))
            cs26 = cs17 + cs25
            cs27 = (d_a(3)*d_a(3))
            cs28 = cs17 + cs27
            cs29 = (2.0_wp/3.0_wp)*cs15
            cs30 = cs20*cs8
            cs31 = cs30*(cs29 + 1.0_wp)
            cs32 = cs31*d_a(3)
            cs33 = cs14*cs15
            cs34 = cs10*cs19
            cs35 = cs34*(cs15 + 1.0_wp)
            cs36 = cs35*d_a(3)
            cs37 = cs15*cs25
            cs38 = cs15*cs27
            cs39 = cs12*cs20
            cs40 = cs39*((1.0_wp/2.0_wp)*cs15 + 1.0_wp)
            cs41 = cs40*d_a(3)
            at0(1) = u
            at0(2) = cs0
            at0(3) = cs1
            at0(4) = cs2
            at1(1, 1) = -cs5*cs6
            at1(2, 1) = -cs7*d_a(2)
            at1(3, 1) = -cs7*d_a(3)
            at1(1, 2) = -cs5*cs8
            at1(2, 2) = -cs9*d_a(2)
            at1(3, 2) = -cs9*d_a(3)
            at1(1, 3) = -cs11*d_a(1)
            at1(2, 3) = -cs11*d_a(2)
            at1(3, 3) = -cs11*d_a(3)
            at1(1, 4) = -cs12*cs5
            at1(2, 4) = -cs13*d_a(2)
            at1(3, 4) = -cs13*d_a(3)
            at2(1, 1, 1) = cs21*(cs14*cs16 + cs18)
            t_at2_p1_01 = cs22*cs23
            at2(1, 2, 1) = t_at2_p1_01
            at2(2, 1, 1) = t_at2_p1_01
            t_at2_p1_02 = cs24*d_a(1)
            at2(1, 3, 1) = t_at2_p1_02
            at2(3, 1, 1) = t_at2_p1_02
            at2(2, 2, 1) = cs21*(cs16*cs25 + cs26)
            t_at2_p1_12 = cs24*d_a(2)
            at2(2, 3, 1) = t_at2_p1_12
            at2(3, 2, 1) = t_at2_p1_12
            at2(3, 3, 1) = cs21*(cs16*cs27 + cs28)
            at2(1, 1, 2) = cs30*(cs14*cs29 + cs18)
            t_at2_p2_01 = cs22*cs31
            at2(1, 2, 2) = t_at2_p2_01
            at2(2, 1, 2) = t_at2_p2_01
            t_at2_p2_02 = cs32*d_a(1)
            at2(1, 3, 2) = t_at2_p2_02
            at2(3, 1, 2) = t_at2_p2_02
            at2(2, 2, 2) = cs30*(cs25*cs29 + cs26)
            t_at2_p2_12 = cs32*d_a(2)
            at2(2, 3, 2) = t_at2_p2_12
            at2(3, 2, 2) = t_at2_p2_12
            at2(3, 3, 2) = cs30*(cs27*cs29 + cs28)
            at2(1, 1, 3) = cs34*(cs18 + cs33)
            t_at2_p3_01 = cs22*cs35
            at2(1, 2, 3) = t_at2_p3_01
            at2(2, 1, 3) = t_at2_p3_01
            t_at2_p3_02 = cs36*d_a(1)
            at2(1, 3, 3) = t_at2_p3_02
            at2(3, 1, 3) = t_at2_p3_02
            at2(2, 2, 3) = cs34*(cs26 + cs37)
            t_at2_p3_12 = cs36*d_a(2)
            at2(2, 3, 3) = t_at2_p3_12
            at2(3, 2, 3) = t_at2_p3_12
            at2(3, 3, 3) = cs34*(cs28 + cs38)
            at2(1, 1, 4) = cs39*(cs18 + (1.0_wp/2.0_wp)*cs33)
            t_at2_q_01 = cs22*cs40
            at2(1, 2, 4) = t_at2_q_01
            at2(2, 1, 4) = t_at2_q_01
            t_at2_q_02 = cs41*d_a(1)
            at2(1, 3, 4) = t_at2_q_02
            at2(3, 1, 4) = t_at2_q_02
            at2(2, 2, 4) = cs39*(cs26 + (1.0_wp/2.0_wp)*cs37)
            t_at2_q_12 = cs41*d_a(2)
            at2(2, 3, 4) = t_at2_q_12
            at2(3, 2, 4) = t_at2_q_12
            at2(3, 3, 4) = cs39*(cs28 + (1.0_wp/2.0_wp)*cs38)
         end block
      case (3)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78
            real(wp) :: cs79, cs80, cs81, cs82, cs83, cs84, cs85, cs86, cs87, cs88, cs89, cs90, cs91
            real(wp) :: cs92, cs93, cs94, cs95, cs96, cs97, cs98, cs99, cs100, cs101, cs102, cs103
            real(wp) :: cs104, cs105, cs106, cs107, cs108, cs109, t_at2_p1_01, t_at2_p1_02
            real(wp) :: t_at2_p1_12, t_at2_p2_01, t_at2_p2_02, t_at2_p2_12, t_at2_p3_01, t_at2_p3_02
            real(wp) :: t_at2_p3_12, t_at2_q_01, t_at2_q_02, t_at2_q_12, t_at3_p1_001, t_at3_p1_002
            real(wp) :: t_at3_p1_011, t_at3_p1_012, t_at3_p1_022, t_at3_p1_112, t_at3_p1_122
            real(wp) :: t_at3_p2_001, t_at3_p2_002, t_at3_p2_011, t_at3_p2_012, t_at3_p2_022
            real(wp) :: t_at3_p2_112, t_at3_p2_122, t_at3_p3_001, t_at3_p3_002, t_at3_p3_011
            real(wp) :: t_at3_p3_012, t_at3_p3_022, t_at3_p3_112, t_at3_p3_122, t_at3_q_001
            real(wp) :: t_at3_q_002, t_at3_q_011, t_at3_q_012, t_at3_q_022, t_at3_q_112, t_at3_q_122

            cs0 = (u*u)
            cs1 = (u*u*u)
            cs2 = (u*sqrt(u))
            cs3 = 1.0_wp/x
            cs4 = blend_k*cs3
            cs5 = cs4*d_a(1)
            cs6 = (1.0_wp/3.0_wp)*u
            cs7 = cs4*cs6
            cs8 = (2.0_wp/3.0_wp)*cs0
            cs9 = cs4*cs8
            cs10 = blend_k*cs1
            cs11 = cs10*cs3
            cs12 = (1.0_wp/2.0_wp)*cs2
            cs13 = cs12*cs4
            cs14 = (d_a(1)*d_a(1))
            cs15 = blend_k*x
            cs16 = (1.0_wp/3.0_wp)*cs15
            cs17 = (x*x)
            cs18 = -cs17
            cs19 = cs14 + cs18
            cs20 = (x*x*x)
            cs21 = 1.0_wp/cs20
            cs22 = blend_k*cs21
            cs23 = cs22*cs6
            cs24 = d_a(1)*d_a(2)
            cs25 = cs23*(cs16 + 1.0_wp)
            cs26 = cs25*d_a(3)
            cs27 = (d_a(2)*d_a(2))
            cs28 = cs18 + cs27
            cs29 = (d_a(3)*d_a(3))
            cs30 = cs18 + cs29
            cs31 = (2.0_wp/3.0_wp)*cs15
            cs32 = cs22*cs8
            cs33 = cs32*(cs31 + 1.0_wp)
            cs34 = cs33*d_a(3)
            cs35 = cs14*cs15
            cs36 = cs10*cs21
            cs37 = cs36*(cs15 + 1.0_wp)
            cs38 = cs37*d_a(3)
            cs39 = cs15*cs27
            cs40 = cs15*cs29
            cs41 = cs12*cs22
            cs42 = cs41*((1.0_wp/2.0_wp)*cs15 + 1.0_wp)
            cs43 = cs42*d_a(3)
            cs44 = -blend_k*cs20
            cs45 = (blend_k*blend_k)
            cs46 = cs14*cs45
            cs47 = (1.0_wp/9.0_wp)*cs46
            cs48 = 3.0_wp*cs14
            cs49 = cs35 + cs48
            cs50 = 1.0_wp/(x*x*x*x*x)
            cs51 = blend_k*cs50
            cs52 = cs51*cs6
            cs53 = cs52*d_a(1)
            cs54 = -1.0_wp/3.0_wp*blend_k*cs20
            cs55 = cs52*(cs17*(1.0_wp - cs47) - cs49 - cs54)
            cs56 = cs27*cs45
            cs57 = (1.0_wp/9.0_wp)*cs56
            cs58 = 3.0_wp*cs27
            cs59 = cs39 + cs58
            cs60 = cs17*(1.0_wp - cs57) - cs54 - cs59
            cs61 = cs17*cs45
            cs62 = cs52*d_a(3)
            cs63 = cs29*cs45
            cs64 = (1.0_wp/9.0_wp)*cs63
            cs65 = 3.0_wp*cs29
            cs66 = cs40 + cs65
            cs67 = cs17*(1.0_wp - cs64) - cs54 - cs66
            cs68 = cs52*d_a(2)
            cs69 = (4.0_wp/9.0_wp)*cs46
            cs70 = -2.0_wp*blend_k*cs20
            cs71 = 2.0_wp*cs35 + cs48
            cs72 = cs51*cs8
            cs73 = cs72*d_a(1)
            cs74 = -2.0_wp/3.0_wp*blend_k*cs20
            cs75 = cs72*(cs17*(1.0_wp - cs69) - cs71 - cs74)
            cs76 = (4.0_wp/9.0_wp)*cs56
            cs77 = 2.0_wp*cs39 + cs58
            cs78 = cs17*(1.0_wp - cs76) - cs74 - cs77
            cs79 = cs72*d_a(3)
            cs80 = (4.0_wp/9.0_wp)*cs63
            cs81 = 2.0_wp*cs40 + cs65
            cs82 = cs17*(1.0_wp - cs80) - cs74 - cs81
            cs83 = cs72*d_a(2)
            cs84 = -3.0_wp*blend_k*cs20
            cs85 = cs15*cs48 + cs48
            cs86 = cs10*cs50
            cs87 = cs86*d_a(1)
            cs88 = cs86*(cs17*(1.0_wp - cs46) - cs44 - cs85)
            cs89 = cs15*cs58 + cs58
            cs90 = cs17*(1.0_wp - cs56) - cs44 - cs89
            cs91 = cs15*cs65 + cs65
            cs92 = cs17*(1.0_wp - cs63) - cs44 - cs91
            cs93 = cs86*d_a(2)
            cs94 = cs86*d_a(3)
            cs95 = (1.0_wp/4.0_wp)*cs46
            cs96 = -3.0_wp/2.0_wp*blend_k*cs20
            cs97 = (3.0_wp/2.0_wp)*cs35 + cs48
            cs98 = cs12*cs51
            cs99 = cs98*d_a(1)
            cs100 = -1.0_wp/2.0_wp*blend_k*cs20
            cs101 = cs98*(-cs100 + cs17*(1.0_wp - cs95) - cs97)
            cs102 = (1.0_wp/4.0_wp)*cs56
            cs103 = (3.0_wp/2.0_wp)*cs39 + cs58
            cs104 = -cs100 - cs103 + cs17*(1.0_wp - cs102)
            cs105 = cs98*d_a(3)
            cs106 = (1.0_wp/4.0_wp)*cs63
            cs107 = (3.0_wp/2.0_wp)*cs40 + cs65
            cs108 = -cs100 - cs107 + cs17*(1.0_wp - cs106)
            cs109 = cs98*d_a(2)
            at0(1) = u
            at0(2) = cs0
            at0(3) = cs1
            at0(4) = cs2
            at1(1, 1) = -cs5*cs6
            at1(2, 1) = -cs7*d_a(2)
            at1(3, 1) = -cs7*d_a(3)
            at1(1, 2) = -cs5*cs8
            at1(2, 2) = -cs9*d_a(2)
            at1(3, 2) = -cs9*d_a(3)
            at1(1, 3) = -cs11*d_a(1)
            at1(2, 3) = -cs11*d_a(2)
            at1(3, 3) = -cs11*d_a(3)
            at1(1, 4) = -cs12*cs5
            at1(2, 4) = -cs13*d_a(2)
            at1(3, 4) = -cs13*d_a(3)
            at2(1, 1, 1) = cs23*(cs14*cs16 + cs19)
            t_at2_p1_01 = cs24*cs25
            at2(1, 2, 1) = t_at2_p1_01
            at2(2, 1, 1) = t_at2_p1_01
            t_at2_p1_02 = cs26*d_a(1)
            at2(1, 3, 1) = t_at2_p1_02
            at2(3, 1, 1) = t_at2_p1_02
            at2(2, 2, 1) = cs23*(cs16*cs27 + cs28)
            t_at2_p1_12 = cs26*d_a(2)
            at2(2, 3, 1) = t_at2_p1_12
            at2(3, 2, 1) = t_at2_p1_12
            at2(3, 3, 1) = cs23*(cs16*cs29 + cs30)
            at2(1, 1, 2) = cs32*(cs14*cs31 + cs19)
            t_at2_p2_01 = cs24*cs33
            at2(1, 2, 2) = t_at2_p2_01
            at2(2, 1, 2) = t_at2_p2_01
            t_at2_p2_02 = cs34*d_a(1)
            at2(1, 3, 2) = t_at2_p2_02
            at2(3, 1, 2) = t_at2_p2_02
            at2(2, 2, 2) = cs32*(cs27*cs31 + cs28)
            t_at2_p2_12 = cs34*d_a(2)
            at2(2, 3, 2) = t_at2_p2_12
            at2(3, 2, 2) = t_at2_p2_12
            at2(3, 3, 2) = cs32*(cs29*cs31 + cs30)
            at2(1, 1, 3) = cs36*(cs19 + cs35)
            t_at2_p3_01 = cs24*cs37
            at2(1, 2, 3) = t_at2_p3_01
            at2(2, 1, 3) = t_at2_p3_01
            t_at2_p3_02 = cs38*d_a(1)
            at2(1, 3, 3) = t_at2_p3_02
            at2(3, 1, 3) = t_at2_p3_02
            at2(2, 2, 3) = cs36*(cs28 + cs39)
            t_at2_p3_12 = cs38*d_a(2)
            at2(2, 3, 3) = t_at2_p3_12
            at2(3, 2, 3) = t_at2_p3_12
            at2(3, 3, 3) = cs36*(cs30 + cs40)
            at2(1, 1, 4) = cs41*(cs19 + (1.0_wp/2.0_wp)*cs35)
            t_at2_q_01 = cs24*cs42
            at2(1, 2, 4) = t_at2_q_01
            at2(2, 1, 4) = t_at2_q_01
            t_at2_q_02 = cs43*d_a(1)
            at2(1, 3, 4) = t_at2_q_02
            at2(3, 1, 4) = t_at2_q_02
