            at4(3, 1, 2, 3, 4) = t_at4_q_0122
            at4(3, 1, 3, 2, 4) = t_at4_q_0122
            at4(3, 2, 1, 3, 4) = t_at4_q_0122
            at4(3, 2, 3, 1, 4) = t_at4_q_0122
            at4(3, 3, 1, 2, 4) = t_at4_q_0122
            at4(3, 3, 2, 1, 4) = t_at4_q_0122
            t_at4_q_0222 = cs243*cs247
            at4(1, 3, 3, 3, 4) = t_at4_q_0222
            at4(3, 1, 3, 3, 4) = t_at4_q_0222
            at4(3, 3, 1, 3, 4) = t_at4_q_0222
            at4(3, 3, 3, 1, 4) = t_at4_q_0222
            at4(2, 2, 2, 2, 4) = &
               cs229*(-cs134*cs242 + cs172*cs225 + cs173 + cs174*(cs237 - 18.0_wp) + cs224 + &
               cs228*cs27*(cs119 - 18.0_wp))
            t_at4_q_1112 = cs236*cs240
            at4(2, 2, 2, 3, 4) = t_at4_q_1112
            at4(2, 2, 3, 2, 4) = t_at4_q_1112
            at4(2, 3, 2, 2, 4) = t_at4_q_1112
            at4(3, 2, 2, 2, 4) = t_at4_q_1112
            t_at4_q_1122 = &
               cs229*(cs134*(-cs120 - cs124) + cs152*(-cs176 + (1.0_wp/2.0_wp)*cs27*cs30*cs44) + &
               cs175 + cs228*(-cs177 + (1.0_wp/4.0_wp)*cs27*cs30*cs44) + cs234 + cs238*cs30)
            at4(2, 2, 3, 3, 4) = t_at4_q_1122
            at4(2, 3, 2, 3, 4) = t_at4_q_1122
            at4(2, 3, 3, 2, 4) = t_at4_q_1122
            at4(3, 2, 2, 3, 4) = t_at4_q_1122
            at4(3, 2, 3, 2, 4) = t_at4_q_1122
            at4(3, 3, 2, 2, 4) = t_at4_q_1122
            t_at4_q_1222 = cs236*cs247
            at4(2, 3, 3, 3, 4) = t_at4_q_1222
            at4(3, 2, 3, 3, 4) = t_at4_q_1222
            at4(3, 3, 2, 3, 4) = t_at4_q_1222
            at4(3, 3, 3, 2, 4) = t_at4_q_1222
            at4(3, 3, 3, 3, 4) = &
               cs229*(-cs134*cs245 + cs178*cs225 + cs179 + cs180*(cs244 - 18.0_wp) + cs224 + &
               cs228*cs30*(cs124 - 18.0_wp))
         end block
      end select

   end subroutine svdw_atom_eval

   !> Per-atom direction-contracted kind tensors of one active atom.
   !>
   !> Sets `aw{n}(i1..in, kind)` = `v_a . d/dR_A` of `at{n}(i1..in, kind)`
   !> = `-sum_alpha v_a(alpha) * at{n+1}(i1..in, alpha, kind)`.
   !>
   !> Contracting the nuclear index here, against the caller's per-atom
   !> displacement direction, is what keeps every `tangent_*` and `hvp_*` output
   !> O(n_active): the caller accumulates `ws* = ws* + aw*` in the same pass that
   !> builds `ps*`, and the full pairwise nuclear tensor is never formed.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    d_a          Displacement r - R_A of the active atom
   !> @param[in]    R_a          Radius of the active atom
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    v_a          Nuclear displacement direction of this atom
   !> @param[in]    max_deriv    Highest spatial-derivative order to set (0..3); a larger value is
   !>                            treated as 3
   !> @param[out]   aw0          Order-0 contracted kind tensor of this atom
   !> @param[out]   aw1          Order-1 contracted kind tensor of this atom
   !> @param[out]   aw2          Order-2 contracted kind tensor of this atom
   !> @param[out]   aw3          Order-3 contracted kind tensor of this atom
   pure subroutine svdw_atom_tangent_eval(d_a, R_a, blend_k, v_a, max_deriv, aw0, aw1, aw2, aw3)
      !> Displacement r - R_A of the active atom
      real(wp), intent(in) :: d_a(3)
      !> Radius of the active atom
      real(wp), intent(in) :: R_a
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> Nuclear displacement direction of this atom
      real(wp), intent(in) :: v_a(3)
      !> Highest spatial-derivative order to set (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> Order-0 contracted kind tensor of this atom
      real(wp), intent(out) :: aw0(nkind)
      !> Order-1 contracted kind tensor of this atom
      real(wp), intent(out) :: aw1(3, nkind)
      !> Order-2 contracted kind tensor of this atom
      real(wp), intent(out) :: aw2(3, 3, nkind)
      !> Order-3 contracted kind tensor of this atom
      real(wp), intent(out) :: aw3(3, 3, 3, nkind)

      !> Distance ||d_a|| and screening factor u = exp(-(blend_k/3)*(x - R_a))
      real(wp) :: x, u

      x = sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3))
      u = exp(-blend_k/3.0_wp*(x - R_a))

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11

            cs0 = blend_k/x
            cs1 = d_a(1)*v_a(1)
            cs2 = cs0*cs1
            cs3 = (1.0_wp/3.0_wp)*u
            cs4 = d_a(2)*v_a(2)
            cs5 = cs0*cs3
            cs6 = d_a(3)*v_a(3)
            cs7 = (2.0_wp/3.0_wp)*(u*u)
            cs8 = cs0*cs7
            cs9 = cs0*(u*u*u)
            cs10 = (1.0_wp/2.0_wp)*(u*sqrt(u))
            cs11 = cs0*cs10
            aw0(1) = cs2*cs3 + cs4*cs5 + cs5*cs6
            aw0(2) = cs2*cs7 + cs4*cs8 + cs6*cs8
            aw0(3) = cs1*cs9 + cs4*cs9 + cs6*cs9
            aw0(4) = cs10*cs2 + cs11*cs4 + cs11*cs6
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46

            cs0 = d_a(1)*v_a(1)
            cs1 = 1.0_wp/x
            cs2 = blend_k*cs1
            cs3 = cs0*cs2
            cs4 = (1.0_wp/3.0_wp)*u
            cs5 = d_a(2)*v_a(2)
            cs6 = cs2*cs4
            cs7 = d_a(3)*v_a(3)
            cs8 = (2.0_wp/3.0_wp)*(u*u)
            cs9 = cs2*cs8
            cs10 = blend_k*(u*u*u)
            cs11 = cs1*cs10
            cs12 = (1.0_wp/2.0_wp)*(u*sqrt(u))
            cs13 = cs12*cs2
            cs14 = cs5*d_a(1)
            cs15 = blend_k*x
            cs16 = (1.0_wp/3.0_wp)*cs15
            cs17 = 1.0_wp/(x*x*x)
            cs18 = blend_k*cs17
            cs19 = cs18*cs4
            cs20 = cs19*(cs16 + 1.0_wp)
            cs21 = cs20*cs7
            cs22 = (d_a(1)*d_a(1))
            cs23 = -(x*x)
            cs24 = cs22 + cs23
            cs25 = cs0*cs20
            cs26 = (d_a(2)*d_a(2))
            cs27 = cs23 + cs26
            cs28 = cs5*d_a(3)
            cs29 = (d_a(3)*d_a(3))
            cs30 = cs23 + cs29
            cs31 = (2.0_wp/3.0_wp)*cs15
            cs32 = cs18*cs8
            cs33 = cs32*(cs31 + 1.0_wp)
            cs34 = cs33*cs7
            cs35 = cs0*cs33
            cs36 = cs10*cs17
            cs37 = cs36*(cs15 + 1.0_wp)
            cs38 = cs37*cs7
            cs39 = cs15*cs22
            cs40 = cs0*cs37
            cs41 = cs15*cs26
            cs42 = cs15*cs29
            cs43 = cs12*cs18
            cs44 = cs43*((1.0_wp/2.0_wp)*cs15 + 1.0_wp)
            cs45 = cs44*cs7
            cs46 = cs0*cs44
            aw0(1) = cs3*cs4 + cs5*cs6 + cs6*cs7
            aw0(2) = cs3*cs8 + cs5*cs9 + cs7*cs9
            aw0(3) = cs0*cs11 + cs11*cs5 + cs11*cs7
            aw0(4) = cs12*cs3 + cs13*cs5 + cs13*cs7
            aw1(1, 1) = -cs14*cs20 - cs19*v_a(1)*(cs16*cs22 + cs24) - cs21*d_a(1)
            aw1(2, 1) = -cs19*v_a(2)*(cs16*cs26 + cs27) - cs21*d_a(2) - cs25*d_a(2)
            aw1(3, 1) = -cs19*v_a(3)*(cs16*cs29 + cs30) - cs20*cs28 - cs25*d_a(3)
            aw1(1, 2) = -cs14*cs33 - cs32*v_a(1)*(cs22*cs31 + cs24) - cs34*d_a(1)
            aw1(2, 2) = -cs32*v_a(2)*(cs26*cs31 + cs27) - cs34*d_a(2) - cs35*d_a(2)
            aw1(3, 2) = -cs28*cs33 - cs32*v_a(3)*(cs29*cs31 + cs30) - cs35*d_a(3)
            aw1(1, 3) = -cs14*cs37 - cs36*v_a(1)*(cs24 + cs39) - cs38*d_a(1)
            aw1(2, 3) = -cs36*v_a(2)*(cs27 + cs41) - cs38*d_a(2) - cs40*d_a(2)
            aw1(3, 3) = -cs28*cs37 - cs36*v_a(3)*(cs30 + cs42) - cs40*d_a(3)
            aw1(1, 4) = -cs14*cs44 - cs43*v_a(1)*(cs24 + (1.0_wp/2.0_wp)*cs39) - cs45*d_a(1)
            aw1(2, 4) = -cs43*v_a(2)*(cs27 + (1.0_wp/2.0_wp)*cs41) - cs45*d_a(2) - cs46*d_a(2)
            aw1(3, 4) = -cs28*cs44 - cs43*v_a(3)*(cs30 + (1.0_wp/2.0_wp)*cs42) - cs46*d_a(3)
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78
            real(wp) :: cs79, cs80, cs81, cs82, cs83, cs84, cs85, cs86, cs87, cs88, cs89, cs90, cs91
            real(wp) :: cs92, cs93, cs94, cs95, cs96, cs97, cs98, cs99, cs100, cs101, cs102, cs103
            real(wp) :: cs104, cs105, cs106, cs107, cs108, cs109, cs110, cs111, cs112, cs113, cs114
            real(wp) :: cs115, cs116, cs117, cs118, cs119, cs120, cs121, cs122, cs123, cs124, cs125
            real(wp) :: cs126, cs127, cs128, cs129, cs130, cs131, cs132, cs133, cs134, cs135, cs136
            real(wp) :: cs137, cs138, cs139, cs140, t_aw2_p1_01, t_aw2_p1_02, t_aw2_p1_12
            real(wp) :: t_aw2_p2_01, t_aw2_p2_02, t_aw2_p2_12, t_aw2_p3_01, t_aw2_p3_02, t_aw2_p3_12
            real(wp) :: t_aw2_q_01, t_aw2_q_02, t_aw2_q_12

            cs0 = d_a(1)*v_a(1)
            cs1 = 1.0_wp/x
            cs2 = blend_k*cs1
            cs3 = cs0*cs2
            cs4 = (1.0_wp/3.0_wp)*u
            cs5 = d_a(2)*v_a(2)
            cs6 = cs2*cs4
            cs7 = d_a(3)*v_a(3)
            cs8 = (2.0_wp/3.0_wp)*(u*u)
            cs9 = cs2*cs8
            cs10 = blend_k*(u*u*u)
            cs11 = cs1*cs10
            cs12 = (1.0_wp/2.0_wp)*(u*sqrt(u))
            cs13 = cs12*cs2
            cs14 = cs5*d_a(1)
            cs15 = blend_k*x
            cs16 = (1.0_wp/3.0_wp)*cs15
            cs17 = (x*x*x)
            cs18 = 1.0_wp/cs17
            cs19 = blend_k*cs18
            cs20 = cs19*cs4
            cs21 = cs20*(cs16 + 1.0_wp)
            cs22 = cs21*cs7
            cs23 = (d_a(1)*d_a(1))
            cs24 = (x*x)
            cs25 = -cs24
            cs26 = cs23 + cs25
            cs27 = cs0*cs21
            cs28 = (d_a(2)*d_a(2))
            cs29 = cs25 + cs28
            cs30 = cs5*d_a(3)
            cs31 = (d_a(3)*d_a(3))
            cs32 = cs25 + cs31
            cs33 = (2.0_wp/3.0_wp)*cs15
            cs34 = cs19*cs8
            cs35 = cs34*(cs33 + 1.0_wp)
            cs36 = cs35*cs7
            cs37 = cs0*cs35
            cs38 = cs10*cs18
            cs39 = cs38*(cs15 + 1.0_wp)
            cs40 = cs39*cs7
            cs41 = cs15*cs23
            cs42 = cs0*cs39
            cs43 = cs15*cs28
            cs44 = cs15*cs31
            cs45 = cs12*cs19
            cs46 = cs45*((1.0_wp/2.0_wp)*cs15 + 1.0_wp)
            cs47 = cs46*cs7
            cs48 = cs0*cs46
            cs49 = -blend_k*cs17
            cs50 = (blend_k*blend_k)
            cs51 = cs23*cs50
            cs52 = (1.0_wp/9.0_wp)*cs51
            cs53 = 3.0_wp*cs23
            cs54 = cs41 + cs53
            cs55 = 1.0_wp/(x*x*x*x*x)
            cs56 = blend_k*cs55
            cs57 = cs4*cs56
            cs58 = cs0*cs57
            cs59 = -1.0_wp/3.0_wp*blend_k*cs17
            cs60 = cs57*(cs24*(1.0_wp - cs52) - cs54 - cs59)
            cs61 = cs24*cs50
            cs62 = -cs15 - 1.0_wp/9.0_wp*cs61 - 3.0_wp
            cs63 = cs57*d_a(1)
            cs64 = cs7*d_a(2)
            cs65 = cs28*cs50
            cs66 = (1.0_wp/9.0_wp)*cs65
            cs67 = 3.0_wp*cs28
            cs68 = cs43 + cs67
            cs69 = cs24*(1.0_wp - cs66) - cs59 - cs68
            cs70 = cs69*v_a(2)
            cs71 = cs60*v_a(1)
            cs72 = cs57*d_a(3)
            cs73 = cs31*cs50
            cs74 = (1.0_wp/9.0_wp)*cs73
            cs75 = 3.0_wp*cs31
            cs76 = cs44 + cs75
            cs77 = cs24*(1.0_wp - cs74) - cs59 - cs76
            cs78 = cs77*v_a(3)
            cs79 = cs5*cs57
            cs80 = cs57*cs7
            cs81 = d_a(2)*d_a(3)
            cs82 = (4.0_wp/9.0_wp)*cs51
            cs83 = -2.0_wp*blend_k*cs17
            cs84 = 2.0_wp*cs41 + cs53
            cs85 = cs56*cs8
            cs86 = cs0*cs85
            cs87 = -2.0_wp/3.0_wp*blend_k*cs17
            cs88 = cs85*(cs24*(1.0_wp - cs82) - cs84 - cs87)
            cs89 = -2.0_wp*cs15 - 4.0_wp/9.0_wp*cs61 - 3.0_wp
            cs90 = cs85*d_a(1)
            cs91 = (4.0_wp/9.0_wp)*cs65
            cs92 = 2.0_wp*cs43 + cs67
            cs93 = cs24*(1.0_wp - cs91) - cs87 - cs92
            cs94 = cs93*v_a(2)
            cs95 = cs88*v_a(1)
            cs96 = cs85*d_a(3)
            cs97 = (4.0_wp/9.0_wp)*cs73
            cs98 = 2.0_wp*cs44 + cs75
            cs99 = cs24*(1.0_wp - cs97) - cs87 - cs98
            cs100 = cs99*v_a(3)
            cs101 = cs5*cs85
            cs102 = cs7*cs85
            cs103 = cs15*cs53 + cs53
            cs104 = cs10*cs55
            cs105 = cs104*(-cs103 + cs24*(1.0_wp - cs51) - cs49)
            cs106 = -3.0_wp*blend_k*cs17
            cs107 = cs0*cs104
            cs108 = -3.0_wp*cs15 - cs61 - 3.0_wp
            cs109 = cs104*d_a(1)
            cs110 = cs108*cs109
            cs111 = cs15*cs67 + cs67
            cs112 = -cs111 + cs24*(1.0_wp - cs65) - cs49
            cs113 = cs112*v_a(2)
            cs114 = cs105*v_a(1)
            cs115 = cs15*cs75 + cs75
            cs116 = -cs115 + cs24*(1.0_wp - cs73) - cs49
            cs117 = cs116*v_a(3)
            cs118 = cs104*cs7
            cs119 = cs104*cs5
            cs120 = (1.0_wp/4.0_wp)*cs51
            cs121 = -3.0_wp/2.0_wp*blend_k*cs17
            cs122 = (3.0_wp/2.0_wp)*cs41 + cs53
            cs123 = cs12*cs56
            cs124 = cs0*cs123
            cs125 = -1.0_wp/2.0_wp*blend_k*cs17
            cs126 = cs123*(-cs122 - cs125 + cs24*(1.0_wp - cs120))
            cs127 = -3.0_wp/2.0_wp*cs15 - 1.0_wp/4.0_wp*cs61 - 3.0_wp
            cs128 = cs123*d_a(1)
            cs129 = (1.0_wp/4.0_wp)*cs65
            cs130 = (3.0_wp/2.0_wp)*cs43 + cs67
            cs131 = -cs125 - cs130 + cs24*(1.0_wp - cs129)
            cs132 = cs131*v_a(2)
            cs133 = cs126*v_a(1)
            cs134 = cs123*d_a(3)
            cs135 = (1.0_wp/4.0_wp)*cs73
            cs136 = (3.0_wp/2.0_wp)*cs44 + cs75
            cs137 = -cs125 - cs136 + cs24*(1.0_wp - cs135)
            cs138 = cs137*v_a(3)
            cs139 = cs123*cs5
            cs140 = cs123*cs7
            aw0(1) = cs3*cs4 + cs5*cs6 + cs6*cs7
            aw0(2) = cs3*cs8 + cs5*cs9 + cs7*cs9
            aw0(3) = cs0*cs11 + cs11*cs5 + cs11*cs7
            aw0(4) = cs12*cs3 + cs13*cs5 + cs13*cs7
            aw1(1, 1) = -cs14*cs21 - cs20*v_a(1)*(cs16*cs23 + cs26) - cs22*d_a(1)
            aw1(2, 1) = -cs20*v_a(2)*(cs16*cs28 + cs29) - cs22*d_a(2) - cs27*d_a(2)
            aw1(3, 1) = -cs20*v_a(3)*(cs16*cs31 + cs32) - cs21*cs30 - cs27*d_a(3)
            aw1(1, 2) = -cs14*cs35 - cs34*v_a(1)*(cs23*cs33 + cs26) - cs36*d_a(1)
            aw1(2, 2) = -cs34*v_a(2)*(cs28*cs33 + cs29) - cs36*d_a(2) - cs37*d_a(2)
            aw1(3, 2) = -cs30*cs35 - cs34*v_a(3)*(cs31*cs33 + cs32) - cs37*d_a(3)
            aw1(1, 3) = -cs14*cs39 - cs38*v_a(1)*(cs26 + cs41) - cs40*d_a(1)
            aw1(2, 3) = -cs38*v_a(2)*(cs29 + cs43) - cs40*d_a(2) - cs42*d_a(2)
            aw1(3, 3) = -cs30*cs39 - cs38*v_a(3)*(cs32 + cs44) - cs42*d_a(3)
            aw1(1, 4) = -cs14*cs46 - cs45*v_a(1)*(cs26 + (1.0_wp/2.0_wp)*cs41) - cs47*d_a(1)
            aw1(2, 4) = -cs45*v_a(2)*(cs29 + (1.0_wp/2.0_wp)*cs43) - cs47*d_a(2) - cs48*d_a(2)
            aw1(3, 4) = -cs30*cs46 - cs45*v_a(3)*(cs32 + (1.0_wp/2.0_wp)*cs44) - cs48*d_a(3)
            aw2(1, 1, 1) = -cs5*cs60 - cs58*(cs24*(3.0_wp - cs52) - cs49 - cs54) - cs60*cs7
            t_aw2_p1_01 = -cs62*cs63*cs64 - cs63*cs70 - cs71*d_a(2)
            aw2(1, 2, 1) = t_aw2_p1_01
            aw2(2, 1, 1) = t_aw2_p1_01
            t_aw2_p1_02 = -cs14*cs62*cs72 - cs63*cs78 - cs71*d_a(3)
            aw2(1, 3, 1) = t_aw2_p1_02
            aw2(3, 1, 1) = t_aw2_p1_02
            aw2(2, 2, 1) = -cs58*cs69 - cs69*cs80 - cs79*(cs24*(3.0_wp - cs66) - cs49 - cs68)
            t_aw2_p1_12 = -cs57*cs78*d_a(2) - cs58*cs62*cs81 - cs70*cs72
            aw2(2, 3, 1) = t_aw2_p1_12
            aw2(3, 2, 1) = t_aw2_p1_12
            aw2(3, 3, 1) = -cs58*cs77 - cs77*cs79 - cs80*(cs24*(3.0_wp - cs74) - cs49 - cs76)
            aw2(1, 1, 2) = -cs5*cs88 - cs7*cs88 - cs86*(cs24*(3.0_wp - cs82) - cs83 - cs84)
            t_aw2_p2_01 = -cs64*cs89*cs90 - cs90*cs94 - cs95*d_a(2)
            aw2(1, 2, 2) = t_aw2_p2_01
            aw2(2, 1, 2) = t_aw2_p2_01
            t_aw2_p2_02 = -cs100*cs90 - cs14*cs89*cs96 - cs95*d_a(3)
