            t_awr3_p1_011 = cs55*cs62
            awr3(1, 2, 2, 1) = t_awr3_p1_011
            awr3(2, 1, 2, 1) = t_awr3_p1_011
            awr3(2, 2, 1, 1) = t_awr3_p1_011
            t_awr3_p1_012 = cs27*cs64*(-cs18 - 1.0_wp/9.0_wp*cs63 - 3.0_wp)
            awr3(1, 2, 3, 1) = t_awr3_p1_012
            awr3(1, 3, 2, 1) = t_awr3_p1_012
            awr3(2, 1, 3, 1) = t_awr3_p1_012
            awr3(2, 3, 1, 1) = t_awr3_p1_012
            awr3(3, 1, 2, 1) = t_awr3_p1_012
            awr3(3, 2, 1, 1) = t_awr3_p1_012
            t_awr3_p1_022 = cs55*cs69
            awr3(1, 3, 3, 1) = t_awr3_p1_022
            awr3(3, 1, 3, 1) = t_awr3_p1_022
            awr3(3, 3, 1, 1) = t_awr3_p1_022
            awr3(2, 2, 2, 1) = cs70*(cs20*(3.0_wp - cs59) - cs47 - cs61)
            t_awr3_p1_112 = cs62*cs64
            awr3(2, 2, 3, 1) = t_awr3_p1_112
            awr3(2, 3, 2, 1) = t_awr3_p1_112
            awr3(3, 2, 2, 1) = t_awr3_p1_112
            t_awr3_p1_122 = cs69*cs70
            awr3(2, 3, 3, 1) = t_awr3_p1_122
            awr3(3, 2, 3, 1) = t_awr3_p1_122
            awr3(3, 3, 2, 1) = t_awr3_p1_122
            awr3(3, 3, 3, 1) = cs64*(cs20*(3.0_wp - cs66) - cs47 - cs68)
            awr3(1, 1, 1, 2) = cs75*(cs20*(3.0_wp - cs71) - cs72 - cs73)
            t_awr3_p2_001 = cs77*d_a(2)
            awr3(1, 1, 2, 2) = t_awr3_p2_001
            awr3(1, 2, 1, 2) = t_awr3_p2_001
            awr3(2, 1, 1, 2) = t_awr3_p2_001
            t_awr3_p2_002 = cs77*d_a(3)
            awr3(1, 1, 3, 2) = t_awr3_p2_002
            awr3(1, 3, 1, 2) = t_awr3_p2_002
            awr3(3, 1, 1, 2) = t_awr3_p2_002
            t_awr3_p2_011 = cs75*cs80
            awr3(1, 2, 2, 2) = t_awr3_p2_011
            awr3(2, 1, 2, 2) = t_awr3_p2_011
            awr3(2, 2, 1, 2) = t_awr3_p2_011
            t_awr3_p2_012 = cs27*cs81*(-2.0_wp*cs18 - 4.0_wp/9.0_wp*cs63 - 3.0_wp)
            awr3(1, 2, 3, 2) = t_awr3_p2_012
            awr3(1, 3, 2, 2) = t_awr3_p2_012
            awr3(2, 1, 3, 2) = t_awr3_p2_012
            awr3(2, 3, 1, 2) = t_awr3_p2_012
            awr3(3, 1, 2, 2) = t_awr3_p2_012
            awr3(3, 2, 1, 2) = t_awr3_p2_012
            t_awr3_p2_022 = cs75*cs84
            awr3(1, 3, 3, 2) = t_awr3_p2_022
            awr3(3, 1, 3, 2) = t_awr3_p2_022
            awr3(3, 3, 1, 2) = t_awr3_p2_022
            awr3(2, 2, 2, 2) = cs85*(cs20*(3.0_wp - cs78) - cs72 - cs79)
            t_awr3_p2_112 = cs80*cs81
            awr3(2, 2, 3, 2) = t_awr3_p2_112
            awr3(2, 3, 2, 2) = t_awr3_p2_112
            awr3(3, 2, 2, 2) = t_awr3_p2_112
            t_awr3_p2_122 = cs84*cs85
            awr3(2, 3, 3, 2) = t_awr3_p2_122
            awr3(3, 2, 3, 2) = t_awr3_p2_122
            awr3(3, 3, 2, 2) = t_awr3_p2_122
            awr3(3, 3, 3, 2) = cs81*(cs20*(3.0_wp - cs82) - cs72 - cs83)
            awr3(1, 1, 1, 3) = cs89*(cs20*(3.0_wp - cs48) - cs86 - cs87)
            t_awr3_p3_001 = cs90*d_a(2)
            awr3(1, 1, 2, 3) = t_awr3_p3_001
            awr3(1, 2, 1, 3) = t_awr3_p3_001
            awr3(2, 1, 1, 3) = t_awr3_p3_001
            t_awr3_p3_002 = cs90*d_a(3)
            awr3(1, 1, 3, 3) = t_awr3_p3_002
            awr3(1, 3, 1, 3) = t_awr3_p3_002
            awr3(3, 1, 1, 3) = t_awr3_p3_002
            t_awr3_p3_011 = cs89*cs92
            awr3(1, 2, 2, 3) = t_awr3_p3_011
            awr3(2, 1, 2, 3) = t_awr3_p3_011
            awr3(2, 2, 1, 3) = t_awr3_p3_011
            t_awr3_p3_012 = cs89*d_a(2)*d_a(3)*(-3.0_wp*cs18 - cs63 - 3.0_wp)
            awr3(1, 2, 3, 3) = t_awr3_p3_012
            awr3(1, 3, 2, 3) = t_awr3_p3_012
            awr3(2, 1, 3, 3) = t_awr3_p3_012
            awr3(2, 3, 1, 3) = t_awr3_p3_012
            awr3(3, 1, 2, 3) = t_awr3_p3_012
            awr3(3, 2, 1, 3) = t_awr3_p3_012
            t_awr3_p3_022 = cs89*cs94
            awr3(1, 3, 3, 3) = t_awr3_p3_022
            awr3(3, 1, 3, 3) = t_awr3_p3_022
            awr3(3, 3, 1, 3) = t_awr3_p3_022
            awr3(2, 2, 2, 3) = cs95*(cs20*(3.0_wp - cs58) - cs86 - cs91)
            t_awr3_p3_112 = cs92*cs96
            awr3(2, 2, 3, 3) = t_awr3_p3_112
            awr3(2, 3, 2, 3) = t_awr3_p3_112
            awr3(3, 2, 2, 3) = t_awr3_p3_112
            t_awr3_p3_122 = cs94*cs95
            awr3(2, 3, 3, 3) = t_awr3_p3_122
            awr3(3, 2, 3, 3) = t_awr3_p3_122
            awr3(3, 3, 2, 3) = t_awr3_p3_122
            awr3(3, 3, 3, 3) = cs96*(cs20*(3.0_wp - cs65) - cs86 - cs93)
            awr3(1, 1, 1, 4) = cs101*(cs20*(3.0_wp - cs97) - cs98 - cs99)
            t_awr3_q_001 = cs103*d_a(2)
            awr3(1, 1, 2, 4) = t_awr3_q_001
            awr3(1, 2, 1, 4) = t_awr3_q_001
            awr3(2, 1, 1, 4) = t_awr3_q_001
            t_awr3_q_002 = cs103*d_a(3)
            awr3(1, 1, 3, 4) = t_awr3_q_002
            awr3(1, 3, 1, 4) = t_awr3_q_002
            awr3(3, 1, 1, 4) = t_awr3_q_002
            t_awr3_q_011 = cs101*cs106
            awr3(1, 2, 2, 4) = t_awr3_q_011
            awr3(2, 1, 2, 4) = t_awr3_q_011
            awr3(2, 2, 1, 4) = t_awr3_q_011
            t_awr3_q_012 = cs107*cs27*(-3.0_wp/2.0_wp*cs18 - 1.0_wp/4.0_wp*cs63 - 3.0_wp)
            awr3(1, 2, 3, 4) = t_awr3_q_012
            awr3(1, 3, 2, 4) = t_awr3_q_012
            awr3(2, 1, 3, 4) = t_awr3_q_012
            awr3(2, 3, 1, 4) = t_awr3_q_012
            awr3(3, 1, 2, 4) = t_awr3_q_012
            awr3(3, 2, 1, 4) = t_awr3_q_012
            t_awr3_q_022 = cs101*cs110
            awr3(1, 3, 3, 4) = t_awr3_q_022
            awr3(3, 1, 3, 4) = t_awr3_q_022
            awr3(3, 3, 1, 4) = t_awr3_q_022
            awr3(2, 2, 2, 4) = cs111*(-cs105 + cs20*(3.0_wp - cs104) - cs98)
            t_awr3_q_112 = cs106*cs107
            awr3(2, 2, 3, 4) = t_awr3_q_112
            awr3(2, 3, 2, 4) = t_awr3_q_112
            awr3(3, 2, 2, 4) = t_awr3_q_112
            t_awr3_q_122 = cs110*cs111
            awr3(2, 3, 3, 4) = t_awr3_q_122
            awr3(3, 2, 3, 4) = t_awr3_q_122
            awr3(3, 3, 2, 4) = t_awr3_q_122
            awr3(3, 3, 3, 4) = cs107*(-cs109 + cs20*(3.0_wp - cs108) - cs98)
         end block
      end select

   end subroutine svdw_atom_radius_tangent_eval

   !> Level-set value and its pure spatial derivatives.
   !>
   !> Assembles `Z = s_1 p3 + (s_2/2)(q^2 - p3) + (s_3/6)(p1^3 - 3 p1 p2 + 2 p3)`
   !> from the accumulated power sums and returns `S = -log(Z)/blend_k` together
   !> with `d^n S / dr^n`, n = 1..max_deriv.  O(1): the O(n_active) work is the
   !> accumulation of `ps*` that the caller did beforehand.
   !>
   !> `f0` is the single shared expression `-log(Z)/blend_k`; there is no second
   !> spelling of it anywhere in this module, so value and gradient stay
   !> bit-for-bit consistent under `-ffp-contract=fast`.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    s_1          One-body blending weight blend_1b
   !> @param[in]    s_2          Two-body blending weight blend_2b
   !> @param[in]    s_3          Three-body blending weight blend_3b
   !> @param[in]    ps0          Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps1          Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps2          Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps3          Accumulated power-sum tensor d^3 p_kind / dr^3, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps4          Accumulated power-sum tensor d^4 p_kind / dr^4, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    max_deriv    Highest spatial-derivative order to compute (0..4); a larger value
   !>                            is treated as 4
   !> @param[out]   f0           Level-set value S = -log(Z)/blend_k
   !> @param[out]   f1_r         Spatial gradient dS/dr
   !> @param[out]   f2_rr        Spatial Hessian d^2S/dr^2
   !> @param[out]   f3_rrr       Third spatial derivative d^3S/dr^3
   !> @param[out]   f4_rrrr      Fourth spatial derivative d^4S/dr^4
   pure subroutine svdw_spatial_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, ps3, ps4, max_deriv, &
                                     f0, f1_r, f2_rr, f3_rrr, f4_rrrr)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Accumulated power-sum tensor d^3 p_kind / dr^3, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps3(3, 3, 3, nkind)
      !> Accumulated power-sum tensor d^4 p_kind / dr^4, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps4(3, 3, 3, 3, nkind)
      !> Highest spatial-derivative order to compute (0..4); a larger value is treated as 4
      integer, intent(in) :: max_deriv
      !> Level-set value S = -log(Z)/blend_k
      real(wp), intent(out) :: f0
      !> Spatial gradient dS/dr
      real(wp), intent(out) :: f1_r(3)
      !> Spatial Hessian d^2S/dr^2
      real(wp), intent(out) :: f2_rr(3, 3)
      !> Third spatial derivative d^3S/dr^3
      real(wp), intent(out) :: f3_rrr(3, 3, 3)
      !> Fourth spatial derivative d^4S/dr^4
      real(wp), intent(out) :: f4_rrrr(3, 3, 3, 3)

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z

      select case (max_deriv)
      case (0)
         block
            f0 = -log(Z)/blend_k
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4

            f0 = -log(Z)/blend_k
            cs0 = ps0(4)*s_2
            cs1 = (1.0_wp/2.0_wp)*ps0(1)*s_3
            cs2 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
            cs3 = (1.0_wp/6.0_wp)*s_3*(3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2))
            cs4 = inv_Z/blend_k
            f1_r(1) = -cs4*(cs0*ps1(1, 4) - cs1*ps1(1, 2) + cs2*ps1(1, 3) + cs3*ps1(1, 1))
            f1_r(2) = -cs4*(cs0*ps1(2, 4) - cs1*ps1(2, 2) + cs2*ps1(2, 3) + cs3*ps1(2, 1))
            f1_r(3) = -cs4*(cs0*ps1(3, 4) - cs1*ps1(3, 2) + cs2*ps1(3, 3) + cs3*ps1(3, 1))
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, t_f2_rr_01, t_f2_rr_02, t_f2_rr_12

            f0 = -log(Z)/blend_k
            cs0 = ps0(4)*s_2
            cs1 = (1.0_wp/2.0_wp)*s_3
            cs2 = cs1*ps1(1, 2)
            cs3 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
            cs4 = (1.0_wp/6.0_wp)*s_3*(3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2))
            cs5 = cs0*ps1(1, 4) - cs2*ps0(1) + cs3*ps1(1, 3) + cs4*ps1(1, 1)
            cs6 = 1.0_wp/blend_k
            cs7 = cs6*inv_Z
            cs8 = cs1*ps1(2, 2)
            cs9 = cs0*ps1(2, 4) + cs3*ps1(2, 3) + cs4*ps1(2, 1) - cs8*ps0(1)
            cs10 = cs1*ps1(3, 2)
            cs11 = cs0*ps1(3, 4) - cs10*ps0(1) + cs3*ps1(3, 3) + cs4*ps1(3, 1)
            cs12 = cs0*cs7
            cs13 = cs7*s_2
            cs14 = cs3*cs7
            cs15 = ps0(1)*s_3
            cs16 = cs7*(cs15*ps1(1, 1) - cs2)
            cs17 = cs4*cs7
            cs18 = (inv_Z*inv_Z)
            cs19 = cs13*ps1(1, 4)
            cs20 = cs7*(cs15*ps1(2, 1) - cs8)
            f1_r(1) = -cs5*cs7
            f1_r(2) = -cs7*cs9
            f1_r(3) = -cs11*cs7
            f2_rr(1, 1) = &
               -cs12*ps2(1, 1, 4) - cs13*(ps1(1, 4)*ps1(1, 4)) - cs14*ps2(1, 1, 3) - cs16*ps1(1, &
               1) - cs17*ps2(1, 1, 1) + cs18*(cs5*cs5)*cs6 + &
               (1.0_wp/2.0_wp)*cs6*inv_Z*ps0(1)*ps2(1, 1, 2)*s_3 + &
               (1.0_wp/2.0_wp)*cs6*inv_Z*ps1(1, 1)*ps1(1, 2)*s_3
            t_f2_rr_01 = &
               -cs12*ps2(1, 2, 4) - cs14*ps2(1, 2, 3) - cs16*ps1(2, 1) - cs17*ps2(1, 2, 1) + &
               cs18*cs5*cs6*cs9 - cs19*ps1(2, 4) + (1.0_wp/2.0_wp)*cs6*inv_Z*ps0(1)*ps2(1, 2, &
               2)*s_3 + (1.0_wp/2.0_wp)*cs6*inv_Z*ps1(1, 1)*ps1(2, 2)*s_3
            f2_rr(1, 2) = t_f2_rr_01
            f2_rr(2, 1) = t_f2_rr_01
            t_f2_rr_02 = &
               cs11*cs18*cs5*cs6 - cs12*ps2(1, 3, 4) - cs14*ps2(1, 3, 3) - cs16*ps1(3, 1) - &
               cs17*ps2(1, 3, 1) - cs19*ps1(3, 4) + (1.0_wp/2.0_wp)*cs6*inv_Z*ps0(1)*ps2(1, 3, &
               2)*s_3 + (1.0_wp/2.0_wp)*cs6*inv_Z*ps1(1, 1)*ps1(3, 2)*s_3
            f2_rr(1, 3) = t_f2_rr_02
            f2_rr(3, 1) = t_f2_rr_02
            f2_rr(2, 2) = &
               -cs12*ps2(2, 2, 4) - cs13*(ps1(2, 4)*ps1(2, 4)) - cs14*ps2(2, 2, 3) - cs17*ps2(2, &
               2, 1) + cs18*cs6*(cs9*cs9) - cs20*ps1(2, 1) + &
               (1.0_wp/2.0_wp)*cs6*inv_Z*ps0(1)*ps2(2, 2, 2)*s_3 + &
               (1.0_wp/2.0_wp)*cs6*inv_Z*ps1(2, 1)*ps1(2, 2)*s_3
            t_f2_rr_12 = &
               cs11*cs18*cs6*cs9 - cs12*ps2(2, 3, 4) - cs13*ps1(2, 4)*ps1(3, 4) - cs14*ps2(2, 3, &
               3) - cs17*ps2(2, 3, 1) - cs20*ps1(3, 1) + (1.0_wp/2.0_wp)*cs6*inv_Z*ps0(1)*ps2(2, &
               3, 2)*s_3 + (1.0_wp/2.0_wp)*cs6*inv_Z*ps1(2, 1)*ps1(3, 2)*s_3
            f2_rr(2, 3) = t_f2_rr_12
            f2_rr(3, 2) = t_f2_rr_12
            f2_rr(3, 3) = &
               (cs11*cs11)*cs18*cs6 - cs12*ps2(3, 3, 4) - cs13*(ps1(3, 4)*ps1(3, 4)) - cs14*ps2(3, &
               3, 3) - cs17*ps2(3, 3, 1) + (1.0_wp/2.0_wp)*cs6*inv_Z*ps0(1)*ps2(3, 3, 2)*s_3 + &
               (1.0_wp/2.0_wp)*cs6*inv_Z*ps1(3, 1)*ps1(3, 2)*s_3 - cs7*ps1(3, 1)*(-cs10 + &
               cs15*ps1(3, 1))
         end block
      case (3)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78
            real(wp) :: cs79, cs80, cs81, cs82, cs83, cs84, cs85, cs86, cs87, cs88, cs89, cs90, cs91
