               3)*(-cs17*cs446 + cs198*cs446 + cs204*cs53 - cs206*cs53 + cs207*cs5 + cs217*ps2(3, &
               3, 1) + 2.0_wp*cs443 + 2.0_wp*cs444 - cs445) + ps3(3, 3, 3, 3)*(cs188 + cs19*cs84) &
               + ps1(3, 4)*(cs136*cs207 - cs144*cs448 - cs144*cs545 + cs144*cs546 + cs144*cs547 + &
               cs144*cs548 + cs19*cs551 - cs22*ps3(3, 3, 3, 4) + cs222*(ps1(3, 4)*ps1(3, 4)*ps1(3, &
               4)) + cs549*ps2(3, 3, 4)) + ps2(3, 3, 4)*(cs0*cs207 + cs19*cs555 + cs194 + &
               cs248*ps2(3, 3, 4) - cs448*cs77 - cs545*cs77 + cs546*cs77 + cs547*cs77 + cs548*cs77 &
               + cs549*ps1(3, 4)) + ps3(3, 3, 3, 4)*(-3.0_wp*cs127 + 3.0_wp*cs129)
         end block
      end select

   end subroutine svdw_spatial_eval

   !> Nuclear derivative of the spatial derivatives, for one active atom A.
   !>
   !> Returns `d/dR_A,s  d^n S / dr^n` for n = 0..max_deriv, i.e. `f1_rA`,
   !> `f2_r_rA`, `f3_rr_rA` and `f4_rrr_rA`.  The trailing index of every result
   !> is the nuclear component s; the leading ones are spatial and fully
   !> symmetric among themselves.
   !>
   !> Because each power sum is a sum over single-atom terms, `d/dR_A` of an
   !> aggregate tensor collapses onto atom A's own tensor with one extra index
   !> and a minus sign.  The routine is therefore O(1) per atom and O(n_active)
   !> over the atom loop, with no pair or triple expansion anywhere.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    s_1          One-body blending weight blend_1b
   !> @param[in]    s_2          Two-body blending weight blend_2b
   !> @param[in]    s_3          Three-body blending weight blend_3b
   !> @param[in]    ps0          Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps1          Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps2          Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps3          Accumulated power-sum tensor d^3 p_kind / dr^3, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    at0          Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at1          Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at2          Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at3          Atom-A kind tensor d^3 u_A^m / dr^3 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at4          Atom-A kind tensor d^4 u_A^m / dr^4 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    max_deriv    Highest *spatial* derivative order to compute (0..3); a larger
   !>                            value is treated as 3
   !> @param[out]   f1_rA        dS/dR_A
   !> @param[out]   f2_r_rA      d^2S/(dr dR_A); index order (spatial, nuclear)
   !> @param[out]   f3_rr_rA     d^3S/(dr^2 dR_A); index order (spatial, spatial, nuclear)
   !> @param[out]   f4_rrr_rA    d^4S/(dr^3 dR_A); index order (spatial x 3, nuclear)
   pure subroutine svdw_nuclear_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, ps3, at0, at1, at2, &
                                     at3, at4, max_deriv, f1_rA, f2_r_rA, f3_rr_rA, f4_rrr_rA)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Accumulated power-sum tensor d^3 p_kind / dr^3, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps3(3, 3, 3, nkind)
      !> Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at0(nkind)
      !> Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at1(3, nkind)
      !> Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at2(3, 3, nkind)
      !> Atom-A kind tensor d^3 u_A^m / dr^3 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at3(3, 3, 3, nkind)
      !> Atom-A kind tensor d^4 u_A^m / dr^4 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at4(3, 3, 3, 3, nkind)
      !> Highest *spatial* derivative order to compute (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> dS/dR_A
      real(wp), intent(out) :: f1_rA(3)
      !> d^2S/(dr dR_A); index order (spatial, nuclear)
      real(wp), intent(out) :: f2_r_rA(3, 3)
      !> d^3S/(dr^2 dR_A); index order (spatial, spatial, nuclear)
      real(wp), intent(out) :: f3_rr_rA(3, 3, 3)
      !> d^4S/(dr^3 dR_A); index order (spatial x 3, nuclear)
      real(wp), intent(out) :: f4_rrr_rA(3, 3, 3, 3)

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3

            cs0 = ps0(4)*s_2
            cs1 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
            cs2 = (1.0_wp/6.0_wp)*s_3*(3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2))
            cs3 = inv_Z/blend_k
            f1_rA(1) = &
               -cs3*(-at1(1, 1)*cs2 + (1.0_wp/2.0_wp)*at1(1, 2)*ps0(1)*s_3 - at1(1, 3)*cs1 - &
               at1(1, 4)*cs0)
            f1_rA(2) = &
               -cs3*(-at1(2, 1)*cs2 + (1.0_wp/2.0_wp)*at1(2, 2)*ps0(1)*s_3 - at1(2, 3)*cs1 - &
               at1(2, 4)*cs0)
            f1_rA(3) = &
               -cs3*(-at1(3, 1)*cs2 + (1.0_wp/2.0_wp)*at1(3, 2)*ps0(1)*s_3 - at1(3, 3)*cs1 - &
               at1(3, 4)*cs0)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34

            cs0 = ps0(4)*s_2
            cs1 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
            cs2 = (1.0_wp/6.0_wp)*s_3*(3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2))
            cs3 = &
               -at1(1, 1)*cs2 + (1.0_wp/2.0_wp)*at1(1, 2)*ps0(1)*s_3 - at1(1, 3)*cs1 - at1(1, &
               4)*cs0
            cs4 = 1.0_wp/blend_k
            cs5 = cs4*inv_Z
            cs6 = &
               -at1(2, 1)*cs2 + (1.0_wp/2.0_wp)*at1(2, 2)*ps0(1)*s_3 - at1(2, 3)*cs1 - at1(2, &
               4)*cs0
            cs7 = &
               -at1(3, 1)*cs2 + (1.0_wp/2.0_wp)*at1(3, 2)*ps0(1)*s_3 - at1(3, 3)*cs1 - at1(3, &
               4)*cs0
            cs8 = cs5*s_2
            cs9 = cs8*ps1(1, 4)
            cs10 = cs0*cs5
            cs11 = (1.0_wp/2.0_wp)*s_3
            cs12 = cs11*cs5
            cs13 = cs12*ps1(1, 1)
            cs14 = cs11*cs5*ps0(1)
            cs15 = cs1*cs5
            cs16 = cs11*ps1(1, 2)
            cs17 = ps0(1)*s_3
            cs18 = cs5*(-cs16 + cs17*ps1(1, 1))
            cs19 = cs2*cs5
            cs20 = cs4*(inv_Z*inv_Z)
            cs21 = cs20*(cs0*ps1(1, 4) + cs1*ps1(1, 3) - cs16*ps0(1) + cs2*ps1(1, 1))
            cs22 = at2(1, 2, 1)*cs19 - at2(1, 2, 2)*cs14 + at2(1, 2, 3)*cs15 + at2(1, 2, 4)*cs10
            cs23 = at2(1, 3, 1)*cs19 - at2(1, 3, 2)*cs14 + at2(1, 3, 3)*cs15 + at2(1, 3, 4)*cs10
            cs24 = cs11*ps1(2, 2)
            cs25 = cs5*(cs17*ps1(2, 1) - cs24)
            cs26 = cs20*(cs0*ps1(2, 4) + cs1*ps1(2, 3) + cs2*ps1(2, 1) - cs24*ps0(1))
            cs27 = cs8*ps1(2, 4)
            cs28 = cs12*ps1(2, 1)
            cs29 = at2(2, 3, 1)*cs19 - at2(2, 3, 2)*cs14 + at2(2, 3, 3)*cs15 + at2(2, 3, 4)*cs10
            cs30 = cs11*ps1(3, 2)
            cs31 = cs5*(cs17*ps1(3, 1) - cs30)
            cs32 = cs20*(cs0*ps1(3, 4) + cs1*ps1(3, 3) + cs2*ps1(3, 1) - cs30*ps0(1))
            cs33 = cs8*ps1(3, 4)
            cs34 = cs12*ps1(3, 1)
            f1_rA(1) = -cs3*cs5
            f1_rA(2) = -cs5*cs6
            f1_rA(3) = -cs5*cs7
            f2_r_rA(1, 1) = &
               at1(1, 1)*cs18 + at2(1, 1, 1)*cs19 - at1(1, 2)*cs13 - at2(1, 1, 2)*cs14 + at2(1, 1, &
               3)*cs15 + at1(1, 4)*cs9 + at2(1, 1, 4)*cs10 + cs21*cs3
            f2_r_rA(1, 2) = at1(2, 1)*cs18 - at1(2, 2)*cs13 + at1(2, 4)*cs9 + cs21*cs6 + cs22
            f2_r_rA(1, 3) = at1(3, 1)*cs18 - at1(3, 2)*cs13 + at1(3, 4)*cs9 + cs21*cs7 + cs23
            f2_r_rA(2, 1) = at1(1, 1)*cs25 - at1(1, 2)*cs28 + at1(1, 4)*cs27 + cs22 + cs26*cs3
            f2_r_rA(2, 2) = &
               at1(2, 1)*cs25 + at2(2, 2, 1)*cs19 - at1(2, 2)*cs28 - at2(2, 2, 2)*cs14 + at2(2, 2, &
               3)*cs15 + at1(2, 4)*cs27 + at2(2, 2, 4)*cs10 + cs26*cs6
            f2_r_rA(2, 3) = at1(3, 1)*cs25 - at1(3, 2)*cs28 + at1(3, 4)*cs27 + cs26*cs7 + cs29
            f2_r_rA(3, 1) = at1(1, 1)*cs31 - at1(1, 2)*cs34 + at1(1, 4)*cs33 + cs23 + cs3*cs32
            f2_r_rA(3, 2) = at1(2, 1)*cs31 - at1(2, 2)*cs34 + at1(2, 4)*cs33 + cs29 + cs32*cs6
            f2_r_rA(3, 3) = &
               at1(3, 1)*cs31 + at2(3, 3, 1)*cs19 - at1(3, 2)*cs34 - at2(3, 3, 2)*cs14 + at2(3, 3, &
               3)*cs15 + at1(3, 4)*cs33 + at2(3, 3, 4)*cs10 + cs32*cs7
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78
            real(wp) :: cs79, cs80, cs81, cs82, cs83, cs84, cs85, cs86, cs87, cs88, cs89, cs90, cs91
            real(wp) :: cs92, cs93, cs94, cs95, cs96, cs97, cs98, cs99, cs100, cs101, cs102, cs103
            real(wp) :: cs104, cs105, cs106, cs107, cs108, cs109, cs110, cs111, cs112, cs113, cs114
            real(wp) :: cs115, cs116, cs117, cs118, cs119, cs120, cs121, cs122, cs123, cs124, cs125
            real(wp) :: cs126, cs127, cs128, cs129, cs130, cs131, cs132, cs133, cs134, cs135, cs136
            real(wp) :: cs137, cs138, cs139, cs140, cs141, cs142, cs143, cs144, cs145, cs146
            real(wp) :: t_f3_rr_rA_010, t_f3_rr_rA_011, t_f3_rr_rA_012, t_f3_rr_rA_020
            real(wp) :: t_f3_rr_rA_021, t_f3_rr_rA_022, t_f3_rr_rA_120, t_f3_rr_rA_121
            real(wp) :: t_f3_rr_rA_122

            cs0 = ps0(4)*s_2
            cs1 = (1.0_wp/3.0_wp)*s_3
            cs2 = cs1 + s_1 - 1.0_wp/2.0_wp*s_2
            cs3 = 3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2)
            cs4 = (1.0_wp/6.0_wp)*cs3*s_3
            cs5 = &
               -at1(1, 1)*cs4 + (1.0_wp/2.0_wp)*at1(1, 2)*ps0(1)*s_3 - at1(1, 3)*cs2 - at1(1, &
               4)*cs0
            cs6 = 1.0_wp/blend_k
            cs7 = cs6*inv_Z
            cs8 = &
               -at1(2, 1)*cs4 + (1.0_wp/2.0_wp)*at1(2, 2)*ps0(1)*s_3 - at1(2, 3)*cs2 - at1(2, &
               4)*cs0
            cs9 = &
               -at1(3, 1)*cs4 + (1.0_wp/2.0_wp)*at1(3, 2)*ps0(1)*s_3 - at1(3, 3)*cs2 - at1(3, &
               4)*cs0
            cs10 = cs7*s_2
            cs11 = cs10*ps1(1, 4)
            cs12 = cs0*cs7
            cs13 = cs7*s_3
            cs14 = cs13*ps1(1, 1)
            cs15 = (1.0_wp/2.0_wp)*cs14
            cs16 = ps0(1)*s_3
            cs17 = (1.0_wp/2.0_wp)*cs16
            cs18 = cs17*cs7
            cs19 = cs2*cs7
            cs20 = ps1(1, 2)*s_3
            cs21 = (1.0_wp/2.0_wp)*cs20
            cs22 = cs16*ps1(1, 1)
            cs23 = -cs21 + cs22
            cs24 = cs23*cs7
            cs25 = cs4*cs7
            cs26 = cs0*ps1(1, 4) + cs2*ps1(1, 3) - cs21*ps0(1) + cs4*ps1(1, 1)
            cs27 = cs6*(inv_Z*inv_Z)
            cs28 = cs26*cs27
            cs29 = at2(1, 2, 1)*cs25 - at2(1, 2, 2)*cs18 + at2(1, 2, 3)*cs19 + at2(1, 2, 4)*cs12
            cs30 = at2(1, 3, 1)*cs25 - at2(1, 3, 2)*cs18 + at2(1, 3, 3)*cs19 + at2(1, 3, 4)*cs12
            cs31 = ps1(2, 2)*s_3
            cs32 = (1.0_wp/2.0_wp)*cs31
            cs33 = cs16*ps1(2, 1)
            cs34 = -cs32 + cs33
            cs35 = cs34*cs7
            cs36 = cs0*ps1(2, 4) + cs2*ps1(2, 3) - cs32*ps0(1) + cs4*ps1(2, 1)
            cs37 = cs27*cs36
            cs38 = cs10*ps1(2, 4)
            cs39 = cs13*ps1(2, 1)
            cs40 = (1.0_wp/2.0_wp)*cs39
            cs41 = at2(2, 3, 1)*cs25 - at2(2, 3, 2)*cs18 + at2(2, 3, 3)*cs19 + at2(2, 3, 4)*cs12
            cs42 = ps1(3, 2)*s_3
            cs43 = (1.0_wp/2.0_wp)*cs42
            cs44 = cs16*ps1(3, 1)
            cs45 = -cs43 + cs44
            cs46 = cs45*cs7
            cs47 = cs0*ps1(3, 4) + cs2*ps1(3, 3) + cs4*ps1(3, 1) - cs43*ps0(1)
            cs48 = cs27*cs47
            cs49 = cs10*ps1(3, 4)
            cs50 = (1.0_wp/2.0_wp)*cs13*ps1(3, 1)
            cs51 = 2.0_wp*s_1 - s_2 + (2.0_wp/3.0_wp)*s_3
            cs52 = cs28*cs51
            cs53 = -cs16*cs28 + cs6*inv_Z*ps1(1, 1)*s_3
            cs54 = ps1(1, 1)*s_3
            cs55 = -cs28*cs54 + (1.0_wp/2.0_wp)*cs6*inv_Z*ps2(1, 1, 1)*s_3
            cs56 = ps1(1, 4)*s_2
            cs57 = -cs10*ps2(1, 1, 4) + 2.0_wp*cs28*cs56
            cs58 = cs0*cs28
            cs59 = -2.0_wp*cs11 + 2.0_wp*cs58
            cs60 = (1.0_wp/2.0_wp)*cs13
            cs61 = cs16*cs7
            cs62 = &
               -cs13*(ps1(1, 1)*ps1(1, 1)) + cs28*(-cs20 + 2.0_wp*cs22) + cs60*ps2(1, 1, 2) - &
               cs61*ps2(1, 1, 1)
            cs63 = -cs24
            cs64 = cs1*cs3
            cs65 = cs21*cs7 - cs22*cs7 + cs28*cs64 + cs63
            cs66 = cs0*cs27
            cs67 = cs27*s_2
            cs68 = cs17*cs27
            cs69 = cs27*ps1(1, 1)
            cs70 = cs2*cs27
            cs71 = cs23*cs27
            cs72 = cs27*cs4
            cs73 = 2.0_wp*cs6*(inv_Z*inv_Z*inv_Z)
            cs74 = &
               -cs21*cs69 - (cs26*cs26)*cs73 + cs66*ps2(1, 1, 4) + cs67*(ps1(1, 4)*ps1(1, 4)) - &
               cs68*ps2(1, 1, 2) + cs70*ps2(1, 1, 3) + cs71*ps1(1, 1) + cs72*ps2(1, 1, 1)
            cs75 = &
               -1.0_wp/6.0_wp*at3(1, 1, 2, 1)*cs3*cs6*inv_Z*s_3 + at3(1, 1, 2, 2)*cs18 - at3(1, 1, &
               2, 3)*cs2*cs6*inv_Z - at3(1, 1, 2, 4)*cs6*inv_Z*ps0(4)*s_2
            cs76 = &
               -1.0_wp/6.0_wp*at3(1, 1, 3, 1)*cs3*cs6*inv_Z*s_3 + at3(1, 1, 3, 2)*cs18 - at3(1, 1, &
               3, 3)*cs2*cs6*inv_Z - at3(1, 1, 3, 4)*cs6*inv_Z*ps0(4)*s_2
            cs77 = -cs14*ps1(2, 1) + cs23*cs37 + cs28*cs34 + cs60*ps2(1, 2, 2) - cs61*ps2(1, 2, 1)
            cs78 = cs37*cs4
            cs79 = cs32*cs7 - cs33*cs7
            cs80 = cs78 + cs79
            cs81 = cs28*cs4 + cs63
            cs82 = (1.0_wp/2.0_wp)*cs54
            cs83 = ps1(2, 1)*s_3
            cs84 = (1.0_wp/2.0_wp)*cs28
            cs85 = -cs37*cs82 + (1.0_wp/2.0_wp)*cs6*inv_Z*ps2(1, 2, 1)*s_3 - cs83*cs84
            cs86 = -cs17*cs37 + (1.0_wp/2.0_wp)*cs6*inv_Z*ps1(2, 1)*s_3
            cs87 = -cs17*cs28 + (1.0_wp/2.0_wp)*cs6*inv_Z*ps1(1, 1)*s_3
            cs88 = cs28*s_2
            cs89 = -cs10*ps2(1, 2, 4) + cs37*cs56 + cs88*ps1(2, 4)
