   !> Same outputs and index order as `svdw_pair_eval`, but with both nuclear
   !> derivatives taken with respect to the *same* atom, which contributes the
   !> extra term `d/dR_A at_k[J] = -at_k[J + s]` that the off-diagonal routine
   !> does not have.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    s_1          One-body blending weight blend_1b
   !> @param[in]    s_2          Two-body blending weight blend_2b
   !> @param[in]    s_3          Three-body blending weight blend_3b
   !> @param[in]    ps0          Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps1          Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps2          Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    at0          Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at1          Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at2          Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at3          Atom-A kind tensor d^3 u_A^m / dr^3 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at4          Atom-A kind tensor d^4 u_A^m / dr^4 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    max_deriv    Highest *spatial* derivative order to compute (0..2); a larger
   !>                            value is treated as 2
   !> @param[out]   f2_rArB      d^2S/(dR_A dR_B); index order (s, t)
   !> @param[out]   f3_r_rArB    d^3S/(dr dR_A dR_B); index order (spatial, s, t)
   !> @param[out]   f4_rr_rArB   d^4S/(dr^2 dR_A dR_B); index order (spatial, spatial, s, t)
   pure subroutine svdw_pair_diag_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, at0, at1, at2, at3, &
                                       at4, max_deriv, f2_rArB, f3_r_rArB, f4_rr_rArB)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at0(nkind)
      !> Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at1(3, nkind)
      !> Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at2(3, 3, nkind)
      !> Atom-A kind tensor d^3 u_A^m / dr^3 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at3(3, 3, 3, nkind)
      !> Atom-A kind tensor d^4 u_A^m / dr^4 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at4(3, 3, 3, 3, nkind)
      !> Highest *spatial* derivative order to compute (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d^2S/(dR_A dR_B); index order (s, t)
      real(wp), intent(out) :: f2_rArB(3, 3)
      !> d^3S/(dr dR_A dR_B); index order (spatial, s, t)
      real(wp), intent(out) :: f3_r_rArB(3, 3, 3)
      !> d^4S/(dr^2 dR_A dR_B); index order (spatial, spatial, s, t)
      real(wp), intent(out) :: f4_rr_rArB(3, 3, 3, 3)

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29

            cs0 = (1.0_wp/2.0_wp)*s_3
            cs1 = at1(1, 2)*cs0
            cs2 = 1.0_wp/blend_k
            cs3 = cs2*inv_Z
            cs4 = at1(1, 1)*cs3
            cs5 = cs0*cs3*ps0(1)
            cs6 = ps0(4)*s_2
            cs7 = cs3*cs6
            cs8 = cs3*s_2
            cs9 = ps0(1)*s_3
            cs10 = cs3*(-at1(1, 1)*cs9 + (1.0_wp/2.0_wp)*at1(1, 2)*s_3)
            cs11 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
            cs12 = -cs11*cs3
            cs13 = (1.0_wp/6.0_wp)*s_3*(3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2))
            cs14 = cs13*cs3
            cs15 = &
               -at1(1, 1)*cs13 + (1.0_wp/2.0_wp)*at1(1, 2)*ps0(1)*s_3 - at1(1, 3)*cs11 - at1(1, &
               4)*cs6
            cs16 = cs2*(inv_Z*inv_Z)
            cs17 = at1(2, 2)*cs0
            cs18 = &
               -at1(2, 1)*cs13 + (1.0_wp/2.0_wp)*at1(2, 2)*ps0(1)*s_3 - at1(2, 3)*cs11 - at1(2, &
               4)*cs6
            cs19 = cs15*cs16
            cs20 = at1(1, 4)*cs8
            cs21 = &
               -at2(1, 2, 1)*cs14 + at2(1, 2, 2)*cs5 + at2(1, 2, 3)*cs12 - at2(1, 2, 4)*cs7 - &
               at1(2, 4)*cs20 + cs18*cs19
            cs22 = at1(3, 2)*cs0
            cs23 = &
               -at1(3, 1)*cs13 + (1.0_wp/2.0_wp)*at1(3, 2)*ps0(1)*s_3 - at1(3, 3)*cs11 - at1(3, &
               4)*cs6
            cs24 = &
               -at2(1, 3, 1)*cs14 + at2(1, 3, 2)*cs5 + at2(1, 3, 3)*cs12 - at2(1, 3, 4)*cs7 - &
               at1(3, 4)*cs20 + cs19*cs23
            cs25 = cs3*(-at1(2, 1)*cs9 + (1.0_wp/2.0_wp)*at1(2, 2)*s_3)
            cs26 = at1(2, 1)*cs3
            cs27 = &
               -at2(2, 3, 1)*cs14 + at2(2, 3, 2)*cs5 + at2(2, 3, 3)*cs12 - at1(2, 4)*at1(3, 4)*cs8 &
               - at2(2, 3, 4)*cs7 + cs16*cs18*cs23
            cs28 = cs3*(-at1(3, 1)*cs9 + (1.0_wp/2.0_wp)*at1(3, 2)*s_3)
            cs29 = at1(3, 1)*cs3
            f2_rArB(1, 1) = &
               at1(1, 1)*cs10 - at2(1, 1, 1)*cs14 + at2(1, 1, 2)*cs5 + at2(1, 1, 3)*cs12 - (at1(1, &
               4)*at1(1, 4))*cs8 - at2(1, 1, 4)*cs7 + cs1*cs4 + (cs15*cs15)*cs16
            f2_rArB(1, 2) = at1(2, 1)*cs10 + cs17*cs4 + cs21
            f2_rArB(1, 3) = at1(3, 1)*cs10 + cs22*cs4 + cs24
            f2_rArB(2, 1) = at1(1, 1)*cs25 + cs1*cs26 + cs21
            f2_rArB(2, 2) = &
               at1(2, 1)*cs25 - at2(2, 2, 1)*cs14 + at2(2, 2, 2)*cs5 + at2(2, 2, 3)*cs12 - (at1(2, &
               4)*at1(2, 4))*cs8 - at2(2, 2, 4)*cs7 + cs16*(cs18*cs18) + cs17*cs26
            f2_rArB(2, 3) = at1(3, 1)*cs25 + cs22*cs26 + cs27
            f2_rArB(3, 1) = at1(1, 1)*cs28 + cs1*cs29 + cs24
            f2_rArB(3, 2) = at1(2, 1)*cs28 + cs17*cs29 + cs27
            f2_rArB(3, 3) = &
               at1(3, 1)*cs28 - at2(3, 3, 1)*cs14 + at2(3, 3, 2)*cs5 + at2(3, 3, 3)*cs12 - (at1(3, &
               4)*at1(3, 4))*cs8 - at2(3, 3, 4)*cs7 + cs16*(cs23*cs23) + cs22*cs29
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78
            real(wp) :: cs79, cs80, cs81, cs82, cs83, cs84, cs85, cs86, cs87, cs88, cs89, cs90, cs91
            real(wp) :: cs92, cs93, cs94, cs95, cs96, cs97, cs98, cs99, cs100, cs101, cs102, cs103
            real(wp) :: cs104, cs105, cs106, cs107, cs108, cs109, cs110, cs111, cs112, cs113, cs114
            real(wp) :: cs115, cs116, cs117, cs118, cs119, cs120, cs121, cs122, cs123, cs124, cs125
            real(wp) :: cs126, cs127, cs128, cs129, cs130, cs131, cs132, cs133, cs134, cs135, cs136
            real(wp) :: cs137, cs138, cs139, cs140, cs141, cs142, cs143, cs144, cs145, cs146, cs147
            real(wp) :: cs148, cs149, cs150, cs151, cs152, cs153, cs154, cs155, cs156, cs157, cs158
            real(wp) :: cs159, cs160, cs161, cs162, cs163, cs164, cs165, cs166, cs167, cs168, cs169
            real(wp) :: cs170, cs171, cs172, cs173, cs174, cs175, cs176, cs177, cs178, cs179, cs180
            real(wp) :: cs181, cs182, cs183, cs184, cs185, cs186, cs187, cs188, cs189, cs190, cs191
            real(wp) :: cs192, cs193, cs194, cs195, cs196, cs197, cs198, cs199

            cs0 = (1.0_wp/2.0_wp)*s_3
            cs1 = 1.0_wp/blend_k
            cs2 = cs1*inv_Z
            cs3 = at1(1, 2)*cs0*cs2
            cs4 = cs0*cs2
            cs5 = at2(1, 1, 2)*cs4
            cs6 = ps0(4)*s_2
            cs7 = cs2*cs6
            cs8 = cs2*s_2
            cs9 = ps0(1)*s_3
            cs10 = at1(1, 1)*cs9
            cs11 = (1.0_wp/2.0_wp)*at1(1, 2)*s_3 - cs10
            cs12 = cs11*cs2
            cs13 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
            cs14 = -cs13
            cs15 = cs14*cs2
            cs16 = (1.0_wp/2.0_wp)*(ps0(1)*ps0(1)) - 1.0_wp/2.0_wp*ps0(2)
            cs17 = cs16*s_3
            cs18 = cs17*cs2
            cs19 = at1(1, 1)*s_3
            cs20 = (1.0_wp/2.0_wp)*at1(1, 2)*ps0(1)*s_3 - at1(1, 3)*cs13 - at1(1, 4)*cs6 - cs16*cs19
            cs21 = (inv_Z*inv_Z)
            cs22 = cs1*cs21
            cs23 = at1(2, 2)*cs0*cs2
            cs24 = &
               -at1(2, 1)*cs17 + (1.0_wp/2.0_wp)*at1(2, 2)*ps0(1)*s_3 - at1(2, 3)*cs13 - at1(2, &
               4)*cs6
            cs25 = cs20*cs22
            cs26 = at2(1, 2, 2)*cs4
            cs27 = at1(1, 4)*cs8
            cs28 = &
               -at2(1, 2, 1)*cs18 + at2(1, 2, 3)*cs15 - at2(1, 2, 4)*cs7 - at1(2, 4)*cs27 + &
               cs24*cs25 + cs26*ps0(1)
            cs29 = at1(3, 2)*cs0*cs2
            cs30 = &
               -at1(3, 1)*cs17 + (1.0_wp/2.0_wp)*at1(3, 2)*ps0(1)*s_3 - at1(3, 3)*cs13 - at1(3, &
               4)*cs6
            cs31 = at2(1, 3, 2)*cs4
            cs32 = &
               -at2(1, 3, 1)*cs18 + at2(1, 3, 3)*cs15 - at2(1, 3, 4)*cs7 - at1(3, 4)*cs27 + &
               cs25*cs30 + cs31*ps0(1)
            cs33 = at1(2, 1)*cs9
            cs34 = (1.0_wp/2.0_wp)*at1(2, 2)*s_3 - cs33
            cs35 = cs2*cs34
            cs36 = at2(2, 2, 2)*cs4
            cs37 = cs22*cs24
            cs38 = at2(2, 3, 2)*cs4
            cs39 = at1(2, 4)*cs8
            cs40 = &
               -at2(2, 3, 1)*cs18 + at2(2, 3, 3)*cs15 - at2(2, 3, 4)*cs7 - at1(3, 4)*cs39 + &
               cs30*cs37 + cs38*ps0(1)
            cs41 = at1(3, 1)*cs9
            cs42 = (1.0_wp/2.0_wp)*at1(3, 2)*s_3 - cs41
            cs43 = cs2*cs42
            cs44 = at2(3, 3, 2)*cs4
            cs45 = cs13*cs2
            cs46 = cs0*ps1(1, 2)
            cs47 = cs13*ps1(1, 3) + cs17*ps1(1, 1) - cs46*ps0(1) + cs6*ps1(1, 4)
            cs48 = cs22*cs47
            cs49 = cs14*cs48
            cs50 = cs13*cs25
            cs51 = cs1*inv_Z*ps1(1, 4)*s_2 - cs48*cs6
            cs52 = cs0*ps0(1)
            cs53 = -cs4*ps1(1, 1) + cs48*cs52
            cs54 = cs25*cs6 + cs27
            cs55 = -at1(1, 1)*cs4 - cs25*cs52
            cs56 = -cs46 + cs9*ps1(1, 1)
            cs57 = cs1*cs56*inv_Z - cs17*cs48
            cs58 = cs10*cs2 + cs17*cs25 - cs3
            cs59 = cs48*s_2
            cs60 = ps1(1, 4)*s_2
            cs61 = -at1(1, 4)*cs59 + at2(1, 1, 4)*cs8 + cs25*cs60
            cs62 = cs0*ps1(1, 1)
            cs63 = (1.0_wp/2.0_wp)*at1(1, 1)*cs1*cs21*cs47*s_3 - at2(1, 1, 1)*cs4 - cs25*cs62
            cs64 = cs2*ps1(1, 1)
            cs65 = cs2*cs9
            cs66 = at2(1, 1, 1)*cs65 + cs11*cs48 + cs19*cs64 + cs25*cs56 - cs5
            cs67 = cs22*cs60
            cs68 = cs22*cs6
            cs69 = cs13*cs22
            cs70 = at2(1, 1, 3)*cs69
            cs71 = cs22*cs56
            cs72 = cs17*cs22
            cs73 = 2.0_wp*cs1*(inv_Z*inv_Z*inv_Z)
            cs74 = cs47*cs73
            cs75 = &
               -at1(1, 1)*cs71 - at2(1, 1, 1)*cs72 + (1.0_wp/2.0_wp)*at1(1, 2)*cs1*cs21*ps1(1, &
               1)*s_3 + (1.0_wp/2.0_wp)*at2(1, 1, 2)*cs1*cs21*ps0(1)*s_3 - at1(1, 4)*cs67 - at2(1, &
               1, 4)*cs68 - cs20*cs74 - cs70
            cs76 = at3(1, 1, 2, 3)*cs45
            cs77 = at3(1, 1, 2, 4)*cs7
            cs78 = -1.0_wp/2.0_wp*at3(1, 1, 2, 2)*cs1*inv_Z*ps0(1)*s_3
            cs79 = at3(1, 1, 2, 1)*cs18
            cs80 = &
               at2(1, 2, 1)*cs57 + at2(1, 2, 2)*cs53 + at2(1, 2, 3)*cs49 + at2(1, 2, 4)*cs51 + &
               cs76 + cs77 + cs78 + cs79
            cs81 = at2(1, 2, 1)*cs58 + at2(1, 2, 2)*cs55 + at2(1, 2, 3)*cs50 + at2(1, 2, 4)*cs54
            cs82 = at3(1, 1, 3, 3)*cs45
            cs83 = at3(1, 1, 3, 4)*cs7
            cs84 = -1.0_wp/2.0_wp*at3(1, 1, 3, 2)*cs1*inv_Z*ps0(1)*s_3
            cs85 = at3(1, 1, 3, 1)*cs18
            cs86 = &
               at2(1, 3, 1)*cs57 + at2(1, 3, 2)*cs53 + at2(1, 3, 3)*cs49 + at2(1, 3, 4)*cs51 + &
               cs82 + cs83 + cs84 + cs85
            cs87 = at2(1, 3, 1)*cs58 + at2(1, 3, 2)*cs55 + at2(1, 3, 3)*cs50 + at2(1, 3, 4)*cs54
            cs88 = cs64*s_3
            cs89 = at2(1, 2, 1)*cs65 - cs26
            cs90 = at1(2, 1)*cs88 + cs34*cs48 + cs37*cs56 + cs89
            cs91 = cs17*cs37 + cs2*cs33 - cs23
            cs92 = at2(1, 2, 1)*cs4
            cs93 = (1.0_wp/2.0_wp)*at1(2, 1)*cs1*cs21*cs47*s_3 - cs37*cs62 - cs92
            cs94 = -at1(2, 1)*cs4 - cs37*cs52
            cs95 = at2(1, 2, 4)*cs8
            cs96 = -at1(2, 4)*cs59 + cs37*cs60 + cs95
            cs97 = cs37*cs6 + cs39
            cs98 = at2(1, 2, 3)*cs69
            cs99 = &
               at2(1, 2, 1)*cs72 - 1.0_wp/2.0_wp*at2(1, 2, 2)*cs1*cs21*ps0(1)*s_3 + at2(1, 2, &
               4)*cs68 + cs98
            cs100 = &
               -at1(2, 1)*cs71 + (1.0_wp/2.0_wp)*at1(2, 2)*cs1*cs21*ps1(1, 1)*s_3 - at1(2, 4)*cs67 &
               - cs24*cs74 - cs99
            cs101 = cs13*cs37
            cs102 = &
               at3(1, 2, 2, 1)*cs18 - 1.0_wp/2.0_wp*at3(1, 2, 2, 2)*cs1*inv_Z*ps0(1)*s_3 + at3(1, &
               2, 2, 3)*cs45 + at3(1, 2, 2, 4)*cs7
            cs103 = &
               at2(1, 2, 1)*cs91 + at2(1, 2, 2)*cs94 + at2(1, 2, 3)*cs101 + at2(1, 2, 4)*cs97 + &
               cs102
            cs104 = &
               at3(1, 2, 3, 1)*cs18 - 1.0_wp/2.0_wp*at3(1, 2, 3, 2)*cs1*inv_Z*ps0(1)*s_3 + at3(1, &
               2, 3, 3)*cs45 + at3(1, 2, 3, 4)*cs7
            cs105 = &
               at2(2, 3, 1)*cs57 + at2(2, 3, 2)*cs53 + at2(2, 3, 3)*cs49 + at2(2, 3, 4)*cs51 + &
               cs104
            cs106 = at2(1, 3, 1)*cs91 + at2(1, 3, 2)*cs94 + at2(1, 3, 3)*cs101 + at2(1, 3, 4)*cs97
            cs107 = at2(1, 3, 1)*cs65 - cs31
            cs108 = at1(3, 1)*cs88 + cs107 + cs30*cs71 + cs42*cs48
            cs109 = cs2*cs41 - cs29 + cs30*cs72
            cs110 = at2(1, 3, 1)*cs4
            cs111 = cs0*cs30
            cs112 = (1.0_wp/2.0_wp)*at1(3, 1)*cs1*cs21*cs47*s_3 - cs110 - cs111*cs22*ps1(1, 1)
            cs113 = -at1(3, 1)*cs4 - cs22*cs30*cs52
            cs114 = at2(1, 3, 4)*cs8
            cs115 = -at1(3, 4)*cs59 + cs114 + cs30*cs67
            cs116 = at1(3, 4)*cs8 + cs30*cs68
            cs117 = at2(1, 3, 3)*cs69
            cs118 = &
               at2(1, 3, 1)*cs72 - 1.0_wp/2.0_wp*at2(1, 3, 2)*cs1*cs21*ps0(1)*s_3 + at2(1, 3, &
               4)*cs68 + cs117
            cs119 = &
               -at1(3, 1)*cs71 + (1.0_wp/2.0_wp)*at1(3, 2)*cs1*cs21*ps1(1, 1)*s_3 - at1(3, 4)*cs67 &
               - cs118 - cs30*cs74
            cs120 = at2(1, 2, 1)*cs109 + at2(1, 2, 2)*cs113 + at2(1, 2, 4)*cs116 + cs30*cs98
            cs121 = &
               at3(1, 3, 3, 1)*cs18 - 1.0_wp/2.0_wp*at3(1, 3, 3, 2)*cs1*inv_Z*ps0(1)*s_3 + at3(1, &
               3, 3, 3)*cs45 + at3(1, 3, 3, 4)*cs7
            cs122 = &
               at2(1, 3, 1)*cs109 + at2(1, 3, 2)*cs113 + at2(1, 3, 4)*cs116 + cs117*cs30 + cs121
            cs123 = cs0*ps1(2, 2)
            cs124 = -cs123*ps0(1) + cs13*ps1(2, 3) + cs17*ps1(2, 1) + cs6*ps1(2, 4)
