               at1(3, 2)*cs830 - at2(3, 3, 2)*cs528 - at2(2, 3, 3)*cs673 - at2(3, 3, 3)*cs532 - &
               at2(2, 3, 4)*cs676 - at1(3, 4)*cs832 - at2(3, 3, 4)*cs538 + cs34*cs833 - cs834 - &
               cs835
            f4_rr_rArB(2, 3, 2, 3) = t_f4_rr_rArB_1212
            f4_rr_rArB(3, 2, 2, 3) = t_f4_rr_rArB_1212
            t_f4_rr_rArB_1220 = &
