               - at2(3, 3, 1)*cs839 - at3(3, 3, 3, 1)*cs159 - at2(2, 3, 2)*cs691 - at3(2, 3, 3, &
               2)*cs223 - at1(3, 2)*cs841 - at2(3, 3, 2)*cs574 - at2(3, 3, 2)*cs816 - at3(3, 3, 3, &
               2)*cs162 - at2(2, 3, 3)*cs694 + at3(2, 3, 3, 3)*cs1*cs15*cs211*cs25 - at2(3, 3, &
               3)*cs580 - at2(3, 3, 3)*cs824 + at3(3, 3, 3, 3)*cs1*cs15*cs150*cs25 - at2(2, 3, &
               4)*cs698 - at3(2, 3, 3, 4)*cs228 - at1(3, 4)*cs843 - at2(3, 3, 4)*cs590 - at2(3, 3, &
               4)*cs821 - at3(3, 3, 3, 4)*cs167 + cs34*cs846 - cs847 - cs848
            f4_rr_rArB(2, 3, 3, 3) = t_f4_rr_rArB_1222
            f4_rr_rArB(3, 2, 3, 3) = t_f4_rr_rArB_1222
            f4_rr_rArB(3, 3, 1, 1) = &
               -at1(1, 1)*cs864 - at2(1, 1, 1)*cs865 - at3(1, 1, 3, 1)*cs866 - at2(1, 3, 1)*cs870 &
               - at1(1, 2)*cs877 - at2(1, 1, 2)*cs878 - at3(1, 1, 3, 2)*cs613 - at2(1, 3, 2)*cs881 &
               - at2(1, 1, 3)*cs897 + at3(1, 1, 3, 3)*cs1*cs211*cs25*cs257 - at2(1, 3, 3)*cs883 - &
               at1(1, 4)*cs890 - at2(1, 1, 4)*cs891 - at3(1, 1, 3, 4)*cs892 - at2(1, 3, 4)*cs894 + &
               cs24*cs896 - cs663
            f4_rr_rArB(3, 3, 1, 2) = &
               -at1(2, 1)*cs864 - at2(2, 3, 1)*cs870 - at1(2, 2)*cs877 - at2(2, 3, 2)*cs881 - &
               at2(2, 3, 3)*cs883 - at1(2, 4)*cs890 - at2(2, 3, 4)*cs894 + cs28*cs896 - cs826 - &
               cs898
            f4_rr_rArB(3, 3, 1, 3) = &
               -at1(3, 1)*cs864 - at2(3, 3, 1)*cs870 - at3(3, 3, 3, 1)*cs67 - at1(3, 2)*cs877 - &
               at2(3, 3, 2)*cs881 - at3(3, 3, 3, 2)*cs62 - at2(3, 3, 3)*cs883 - at3(3, 3, 3, &
               3)*cs55 - at1(3, 4)*cs890 - at2(3, 3, 4)*cs894 - at3(3, 3, 3, 4)*cs60 + cs34*cs896 &
               - cs899
            f4_rr_rArB(3, 3, 2, 1) = &
               -at1(1, 1)*cs901 - at2(1, 3, 1)*cs902 - at1(1, 2)*cs904 - at2(1, 3, 2)*cs905 - &
               at2(1, 3, 3)*cs906 - at1(1, 4)*cs907 - at2(1, 3, 4)*cs908 + cs24*cs909 - cs681 - &
               cs898
            f4_rr_rArB(3, 3, 2, 2) = &
               -at1(2, 1)*cs901 - at2(2, 2, 1)*cs865 - at3(2, 2, 3, 1)*cs866 - at2(2, 3, 1)*cs902 &
               - at1(2, 2)*cs904 - at2(2, 2, 2)*cs878 - at3(2, 2, 3, 2)*cs613 - at2(2, 3, 2)*cs905 &
               - at2(2, 2, 3)*cs897 + at3(2, 2, 3, 3)*cs1*cs211*cs25*cs257 - at2(2, 3, 3)*cs906 - &
               at1(2, 4)*cs907 - at2(2, 2, 4)*cs891 - at3(2, 2, 3, 4)*cs892 - at2(2, 3, 4)*cs908 + &
               cs28*cs909 - cs834
            f4_rr_rArB(3, 3, 2, 3) = &
               -at1(3, 1)*cs901 - at2(3, 3, 1)*cs902 - at3(3, 3, 3, 1)*cs105 - at1(3, 2)*cs904 - &
               at2(3, 3, 2)*cs905 - at3(3, 3, 3, 2)*cs109 - at2(3, 3, 3)*cs906 - at3(3, 3, 3, &
               3)*cs120 - at1(3, 4)*cs907 - at2(3, 3, 4)*cs908 - at3(3, 3, 3, 4)*cs112 + &
               cs34*cs909 - cs910
            f4_rr_rArB(3, 3, 3, 1) = &
               -at1(1, 1)*cs912 - at2(1, 3, 1)*cs914 - at1(1, 2)*cs916 - at2(1, 3, 2)*cs917 - &
               at2(1, 3, 3)*cs918 - at1(1, 4)*cs920 - at2(1, 3, 4)*cs921 + cs24*cs923 - cs704 - &
               cs899
            f4_rr_rArB(3, 3, 3, 2) = &
               -at1(2, 1)*cs912 - at2(2, 3, 1)*cs914 - at1(2, 2)*cs916 - at2(2, 3, 2)*cs917 - &
               at2(2, 3, 3)*cs918 - at1(2, 4)*cs920 - at2(2, 3, 4)*cs921 + cs28*cs923 - cs848 - &
               cs910
            f4_rr_rArB(3, 3, 3, 3) = &
               -at1(3, 1)*cs912 - at2(3, 3, 1)*cs865 - at2(3, 3, 1)*cs914 - at3(3, 3, 3, 1)*cs128 &
               - at3(3, 3, 3, 1)*cs866 - at4(3, 3, 3, 3, 1)*cs22 - at1(3, 2)*cs916 - at2(3, 3, &
               2)*cs878 - at2(3, 3, 2)*cs917 - at3(3, 3, 3, 2)*cs134 - at3(3, 3, 3, 2)*cs613 + &
               (1.0_wp/2.0_wp)*at4(3, 3, 3, 3, 2)*cs1*inv_Z*ps0(1)*s_3 - at2(3, 3, 3)*cs897 - &
               at2(3, 3, 3)*cs918 + at3(3, 3, 3, 3)*cs1*cs211*cs25*cs257 - at4(3, 3, 3, 3, 3)*cs49 &
               - at1(3, 4)*cs920 - at2(3, 3, 4)*cs891 - at2(3, 3, 4)*cs921 - at3(3, 3, 3, 4)*cs137 &
               - at3(3, 3, 3, 4)*cs892 - at4(3, 3, 3, 3, 4)*cs7 - cs34*cs922 + cs34*cs923
         end block
      end select

   end subroutine svdw_pair_diag_eval

   !> Second *radius* derivative of the spatial derivatives, for A /= B.
   !>
   !> Returns `d^2/(dR_a dR_b) d^n S / dr^n` for n = 0..max_deriv, i.e.
   !> `f2_radrad`, `f3_r_radrad` and `f4_rr_radrad`, where `R_a` and `R_b` are the
   !> *radii* of atoms A and B.  Radii are scalars, so neither derivative appends
   !> an index: the rank of every result is the spatial order, two less than the
   !> corresponding `svdw_pair_eval` output.
   !>
   !> `at` and `aw` carry no `R_b` dependence, so the entire cross-radius coupling
   !> comes from the nonlinearity of Z in the power sums and from the log -- the
   !> same statement as for `f2_rArB`.  Call `svdw_radpair_diag_eval` instead when
   !> A == B, which adds the extra single-tensor term.
   !>
   !> This is the uncontracted form of `svdw_radius_hvp_eval`'s radius-radius
   !> half; prefer that routine unless the O(n_active**2) tensor itself is wanted.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    s_1          One-body blending weight blend_1b
   !> @param[in]    s_2          Two-body blending weight blend_2b
   !> @param[in]    s_3          Three-body blending weight blend_3b
   !> @param[in]    ps0          Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps1          Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps2          Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    at0          Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at1          Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at2          Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    bt0          Atom-B kind tensor d^0 u_B^m / dr^0 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    bt1          Atom-B kind tensor d^1 u_B^m / dr^1 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    bt2          Atom-B kind tensor d^2 u_B^m / dr^2 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    max_deriv    Highest *spatial* derivative order to compute (0..2); a larger
   !>                            value is treated as 2
   !> @param[out]   f2_radrad    d^2S/(dR_a dR_b)
   !> @param[out]   f3_r_radrad  d^3S/(dr dR_a dR_b)
   !> @param[out]   f4_rr_radrad d^4S/(dr^2 dR_a dR_b)
   pure subroutine svdw_radpair_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, at0, at1, at2, bt0, &
                                     bt1, bt2, max_deriv, f2_radrad, f3_r_radrad, f4_rr_radrad)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at0(nkind)
      !> Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at1(3, nkind)
      !> Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at2(3, 3, nkind)
      !> Atom-B kind tensor d^0 u_B^m / dr^0 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: bt0(nkind)
      !> Atom-B kind tensor d^1 u_B^m / dr^1 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: bt1(3, nkind)
      !> Atom-B kind tensor d^2 u_B^m / dr^2 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: bt2(3, 3, nkind)
      !> Highest *spatial* derivative order to compute (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d^2S/(dR_a dR_b)
      real(wp), intent(out) :: f2_radrad
      !> d^3S/(dr dR_a dR_b)
      real(wp), intent(out) :: f3_r_radrad(3)
      !> d^4S/(dr^2 dR_a dR_b)
      real(wp), intent(out) :: f4_rr_radrad(3, 3)

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9

            cs0 = at0(1)*blend_k*s_3
            cs1 = at0(4)*blend_k
            cs2 = (1.0_wp/3.0_wp)*s_3
            cs3 = blend_k*cs2
            cs4 = at0(2)*cs3
            cs5 = cs3*ps0(1)
            cs6 = (1.0_wp/2.0_wp)*s_2
            cs7 = cs6*ps0(4)
            cs8 = blend_k*(cs2 - cs6 + s_1)
            cs9 = (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)) - 1.0_wp/6.0_wp*ps0(2)
            f2_radrad = &
               -1.0_wp/3.0_wp*bt0(1)*inv_Z*(at0(1)*cs5 - cs4) + (1.0_wp/9.0_wp)*bt0(2)*cs0*inv_Z - &
               1.0_wp/4.0_wp*bt0(4)*cs1*inv_Z*s_2 + (inv_Z*inv_Z)*(at0(3)*cs8 + cs0*cs9 + cs1*cs7 &
               - cs4*ps0(1))*(blend_k*bt0(1)*cs9*s_3 + blend_k*bt0(4)*cs7 - bt0(2)*cs5 + &
               bt0(3)*cs8)/blend_k
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61

            cs0 = at0(1)*blend_k
            cs1 = cs0*s_3
            cs2 = (1.0_wp/3.0_wp)*s_3
            cs3 = at0(2)*cs2
            cs4 = blend_k*cs3
            cs5 = cs2*ps0(1)
            cs6 = cs0*cs5 - cs4
            cs7 = (1.0_wp/3.0_wp)*bt0(1)
            cs8 = (1.0_wp/2.0_wp)*s_2
            cs9 = blend_k*ps0(4)
            cs10 = cs2 - cs8 + s_1
            cs11 = blend_k*cs10
            cs12 = 3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2)
            cs13 = (1.0_wp/18.0_wp)*cs12
            cs14 = cs13*s_3
            cs15 = blend_k*bt0(1)*cs14 - blend_k*bt0(2)*cs5 + bt0(3)*cs11 + bt0(4)*cs8*cs9
            cs16 = at0(4)*cs8
            cs17 = at0(3)*cs11 + cs1*cs13 + cs16*cs9 - cs4*ps0(1)
            cs18 = (inv_Z*inv_Z)
            cs19 = 1.0_wp/blend_k
            cs20 = cs18*cs19
            cs21 = cs17*cs20
            cs22 = cs10*cs18
            cs23 = cs17*cs22
            cs24 = cs8*inv_Z
            cs25 = (1.0_wp/2.0_wp)*blend_k
            cs26 = cs25*(-at0(4)*cs24 + cs17*cs18*cs19*ps0(4)*s_2)
            cs27 = (1.0_wp/6.0_wp)*s_3
            cs28 = (1.0_wp/2.0_wp)*s_3
            cs29 = cs21*cs28
            cs30 = (2.0_wp/3.0_wp)*blend_k
            cs31 = cs30*(at0(1)*cs27*inv_Z - cs29*ps0(1))
            cs32 = cs2*inv_Z
            cs33 = at0(1)*cs32
            cs34 = cs12*cs27
            cs35 = (1.0_wp/3.0_wp)*blend_k*(cs21*cs34 + cs3*inv_Z - cs33*ps0(1))
            cs36 = ps0(4)*s_2
            cs37 = cs28*ps1(1, 2)
            cs38 = cs10*ps1(1, 3) + cs34*ps1(1, 1) + cs36*ps1(1, 4) - cs37*ps0(1)
            cs39 = cs16*cs18
            cs40 = cs21*s_2
            cs41 = bt0(4)*cs25
            cs42 = at0(1)*cs18
            cs43 = cs27*cs42
