   !> Second *radius* derivative of the spatial derivatives, for A == B.
   !>
   !> Same outputs and ranks as `svdw_radpair_eval`, but with both derivatives
   !> taken with respect to the same radius, which contributes the extra term
   !> `d/dR_a at_k[J] = (blend_k m_k / 3) at_k[J]` that the off-diagonal routine
   !> does not have.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    s_1          One-body blending weight blend_1b
   !> @param[in]    s_2          Two-body blending weight blend_2b
   !> @param[in]    s_3          Three-body blending weight blend_3b
   !> @param[in]    ps0          Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps1          Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps2          Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    at0          Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at1          Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at2          Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    max_deriv    Highest *spatial* derivative order to compute (0..2); a larger
   !>                            value is treated as 2
   !> @param[out]   f2_radrad    d^2S/(dR_a dR_b)
   !> @param[out]   f3_r_radrad  d^3S/(dr dR_a dR_b)
   !> @param[out]   f4_rr_radrad d^4S/(dr^2 dR_a dR_b)
   pure subroutine svdw_radpair_diag_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, at0, at1, at2, &
                                          max_deriv, f2_radrad, f3_r_radrad, f4_rr_radrad)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at0(nkind)
      !> Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at1(3, nkind)
      !> Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at2(3, 3, nkind)
      !> Highest *spatial* derivative order to compute (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d^2S/(dR_a dR_b)
      real(wp), intent(out) :: f2_radrad
      !> d^3S/(dr dR_a dR_b)
      real(wp), intent(out) :: f3_r_radrad(3)
      !> d^4S/(dr^2 dR_a dR_b)
      real(wp), intent(out) :: f4_rr_radrad(3, 3)

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8

            cs0 = at0(4)*blend_k*ps0(4)
            cs1 = (1.0_wp/4.0_wp)*inv_Z*s_2
            cs2 = (1.0_wp/2.0_wp)*s_2
            cs3 = (1.0_wp/3.0_wp)*s_3
            cs4 = at0(3)*blend_k*(-cs2 + cs3 + s_1)
            cs5 = at0(1)*inv_Z
            cs6 = blend_k*s_3*(3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2))
            cs7 = blend_k*cs3
            cs8 = at0(2)*cs7
            f2_radrad = &
               (1.0_wp/9.0_wp)*at0(1)*at0(2)*blend_k*inv_Z*s_3 + &
               (2.0_wp/9.0_wp)*at0(2)*blend_k*inv_Z*ps0(1)*s_3 - (at0(4)*at0(4))*blend_k*cs1 - &
               cs0*cs1 - cs4*inv_Z - 1.0_wp/54.0_wp*cs5*cs6 - 1.0_wp/3.0_wp*cs5*(at0(1)*cs7*ps0(1) &
               - cs8) + (inv_Z*inv_Z)*(((1.0_wp/18.0_wp)*at0(1)*cs6 + cs0*cs2 + cs4 - &
               cs8*ps0(1))*((1.0_wp/18.0_wp)*at0(1)*cs6 + cs0*cs2 + cs4 - cs8*ps0(1)))/blend_k
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67, cs68, cs69, cs70, cs71, cs72

            cs0 = ps0(4)*s_2
            cs1 = blend_k*inv_Z
            cs2 = (1.0_wp/4.0_wp)*cs1
            cs3 = cs0*cs2
            cs4 = (1.0_wp/2.0_wp)*s_2
            cs5 = (1.0_wp/3.0_wp)*s_3
            cs6 = -cs4 + cs5 + s_1
            cs7 = blend_k*cs6
            cs8 = at0(3)*cs7
            cs9 = at0(1)*blend_k
            cs10 = 3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2)
            cs11 = cs10*s_3
            cs12 = (1.0_wp/54.0_wp)*cs11
            cs13 = at0(2)*cs5
            cs14 = blend_k*cs13
            cs15 = cs5*ps0(1)
            cs16 = -cs14 + cs15*cs9
            cs17 = (1.0_wp/3.0_wp)*inv_Z
            cs18 = 1.0_wp/blend_k
            cs19 = (inv_Z*inv_Z)
            cs20 = at0(4)*cs4
            cs21 = (1.0_wp/18.0_wp)*cs11
            cs22 = blend_k*cs20*ps0(4) - cs14*ps0(1) + cs21*cs9 + cs8
            cs23 = ps0(1)*s_3
            cs24 = (2.0_wp/9.0_wp)*cs1*cs23
            cs25 = cs7*inv_Z
            cs26 = at1(1, 1)*blend_k
            cs27 = (1.0_wp/2.0_wp)*s_3
            cs28 = cs27*ps1(1, 2)
            cs29 = (1.0_wp/6.0_wp)*s_3
            cs30 = cs10*cs29
            cs31 = cs0*ps1(1, 4) - cs28*ps0(1) + cs30*ps1(1, 1) + cs6*ps1(1, 3)
            cs32 = cs19*cs31
            cs33 = cs15*cs19
            cs34 = (2.0_wp/3.0_wp)*blend_k
            cs35 = at0(2)*cs34
            cs36 = cs4*inv_Z
            cs37 = cs19*cs4*ps0(4)
            cs38 = (1.0_wp/2.0_wp)*blend_k
            cs39 = at0(4)*cs38
            cs40 = cs19*cs6
            cs41 = at1(1, 3)*cs40
            cs42 = cs38*(-at0(4)*cs36 + cs18*cs19*cs22*ps0(4)*s_2)
            cs43 = cs18*cs19
            cs44 = cs22*cs43
            cs45 = cs27*cs44
            cs46 = cs34*(at0(1)*cs29*inv_Z - cs45*ps0(1))
            cs47 = cs23*ps1(1, 1) - cs28
            cs48 = cs19*cs21
            cs49 = (1.0_wp/3.0_wp)*at0(1)
            cs50 = blend_k*cs49
            cs51 = cs5*inv_Z
            cs52 = cs51*ps0(1)
            cs53 = &
               -1.0_wp/3.0_wp*at0(1)*cs52 + (1.0_wp/3.0_wp)*cs13*inv_Z + (1.0_wp/3.0_wp)*cs30*cs44
            cs54 = cs19*cs20
            cs55 = cs44*s_2
            cs56 = at0(1)*cs29
            cs57 = cs16*cs43
            cs58 = cs13*cs19
            cs59 = cs19*cs49
            cs60 = 2.0_wp*cs18*cs22*(inv_Z*inv_Z*inv_Z)
            cs61 = cs1*cs12
            cs62 = cs27*ps1(2, 2)
            cs63 = cs0*ps1(2, 4) + cs30*ps1(2, 1) + cs6*ps1(2, 3) - cs62*ps0(1)
            cs64 = cs19*cs63
            cs65 = at1(2, 3)*cs40
            cs66 = cs23*ps1(2, 1) - cs62
            cs67 = blend_k*cs53
            cs68 = cs27*ps1(3, 2)
            cs69 = cs0*ps1(3, 4) + cs30*ps1(3, 1) + cs6*ps1(3, 3) - cs68*ps0(1)
            cs70 = cs19*cs69
            cs71 = at1(3, 3)*cs40
            cs72 = cs23*ps1(3, 1) - cs68
            f2_radrad = &
               (1.0_wp/9.0_wp)*at0(1)*at0(2)*blend_k*inv_Z*s_3 - at0(1)*cs16*cs17 + &
               (2.0_wp/9.0_wp)*at0(2)*blend_k*inv_Z*ps0(1)*s_3 - (at0(4)*at0(4))*cs2*s_2 - &
               at0(4)*cs3 - cs12*cs9*inv_Z + cs18*cs19*(cs22*cs22) - cs8*inv_Z
            f3_r_radrad(1) = &
