               cs12*cs26*inv_Z + cs22*cs41 + cs22*(at1(1, 1)*cs48 - at1(1, 2)*cs33 + at1(1, &
               4)*cs37 - cs31*cs60 + cs41 + cs47*cs59 + cs54*ps1(1, 4) - cs58*ps1(1, 1)) + &
               cs26*cs53 + cs32*cs8 + cs35*(-cs31*cs33 + (1.0_wp/3.0_wp)*inv_Z*ps1(1, 1)*s_3) + &
               cs35*((1.0_wp/6.0_wp)*at1(1, 1)*inv_Z*s_3 - cs32*cs56 - cs45*ps1(1, 1)) + &
               cs39*(cs31*cs37 - cs36*ps1(1, 4)) + cs39*(-at1(1, 4)*cs36 + cs31*cs54 + cs55*ps1(1, &
               4)) + cs50*(-cs17*cs47 + cs31*cs48) + cs50*(-at0(1)*cs51*ps1(1, 1) - at1(1, 1)*cs52 &
               + at1(1, 2)*cs51 + cs31*cs57 + cs44*cs47)
            f3_r_radrad(2) = &
               -at1(2, 1)*cs61 + at1(2, 1)*cs67 + at1(2, 2)*cs24 + at1(2, 2)*cs46 - at1(2, 3)*cs25 &
               - at1(2, 4)*cs3 + at1(2, 4)*cs42 + cs22*cs65 + cs22*(at1(2, 1)*cs48 - at1(2, &
               2)*cs33 + at1(2, 4)*cs37 + cs54*ps1(2, 4) - cs58*ps1(2, 1) + cs59*cs66 - cs60*cs63 &
               + cs65) + cs35*(-cs33*cs63 + (1.0_wp/3.0_wp)*inv_Z*ps1(2, 1)*s_3) + &
               cs35*((1.0_wp/6.0_wp)*at1(2, 1)*inv_Z*s_3 - cs45*ps1(2, 1) - cs56*cs64) + &
               cs39*(-cs36*ps1(2, 4) + cs37*cs63) + cs39*(-at1(2, 4)*cs36 + cs54*cs63 + &
               cs55*ps1(2, 4)) + cs50*(-cs17*cs66 + cs48*cs63) + cs50*(-at0(1)*cs51*ps1(2, 1) - &
               at1(2, 1)*cs52 + at1(2, 2)*cs51 + cs44*cs66 + cs57*cs63) + cs64*cs8
            f3_r_radrad(3) = &
               -at1(3, 1)*cs61 + at1(3, 1)*cs67 + at1(3, 2)*cs24 + at1(3, 2)*cs46 - at1(3, 3)*cs25 &
               - at1(3, 4)*cs3 + at1(3, 4)*cs42 + cs22*cs71 + cs22*(at1(3, 1)*cs48 - at1(3, &
               2)*cs33 + at1(3, 4)*cs37 + cs54*ps1(3, 4) - cs58*ps1(3, 1) + cs59*cs72 - cs60*cs69 &
               + cs71) + cs35*(-cs33*cs69 + (1.0_wp/3.0_wp)*inv_Z*ps1(3, 1)*s_3) + &
               cs35*((1.0_wp/6.0_wp)*at1(3, 1)*inv_Z*s_3 - cs45*ps1(3, 1) - cs56*cs70) + &
               cs39*(-cs36*ps1(3, 4) + cs37*cs69) + cs39*(-at1(3, 4)*cs36 + cs54*cs69 + &
               cs55*ps1(3, 4)) + cs50*(-cs17*cs72 + cs48*cs69) + cs50*(-at0(1)*cs51*ps1(3, 1) - &
               at1(3, 1)*cs52 + at1(3, 2)*cs51 + cs44*cs72 + cs57*cs69) + cs70*cs8
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78
            real(wp) :: cs79, cs80, cs81, cs82, cs83, cs84, cs85, cs86, cs87, cs88, cs89, cs90, cs91
            real(wp) :: cs92, cs93, cs94, cs95, cs96, cs97, cs98, cs99, cs100, cs101, cs102, cs103
            real(wp) :: cs104, cs105, cs106, cs107, cs108, cs109, cs110, cs111, cs112, cs113, cs114
            real(wp) :: cs115, cs116, cs117, cs118, cs119, cs120, cs121, cs122, cs123, cs124, cs125
            real(wp) :: cs126, cs127, cs128, cs129, cs130, cs131, cs132, cs133, cs134, cs135, cs136
