               cs261*cs348 + cs355*cs90 - cs355*cs98 + cs38*cs434 + cs435*cs55) + cs427*(cs244 + &
               cs391) + cs55*(cs22*cs431 + cs54*(cs108*cs96 + cs116*cs88 + cs165*ps2(2, 3, 2) - &
               cs166*ps2(2, 3, 1) - cs306*ps1(3, 1))) + cs55*(-at2(2, 3, 1)*cs57 + at2(2, 3, &
               2)*cs56 + cs100*cs112 + cs110*cs92 + cs112*cs90 + cs120*cs92 + cs17*cs429 + &
               cs23*cs441 + cs280*cs373 + cs284*cs367 + cs294*cs364 + cs308*cs360 + cs38*cs438 + &
               cs42*cs435 + cs55*(cs108*cs94 + 2.0_wp*cs112*cs96 - cs131*ps2(2, 3, 1) + &
               cs282*ps1(3, 1)))
            f4_rr_radrad(2, 3) = t_f4_rr_radrad_12
            f4_rr_radrad(3, 2) = t_f4_rr_radrad_12
            f4_rr_radrad(3, 3) = &
               -at2(3, 3, 1)*cs29 + at2(3, 3, 1)*cs60 + at2(3, 3, 2)*cs26 + at2(3, 3, 2)*cs50 - &
               at2(3, 3, 3)*cs28 - at2(3, 3, 4)*cs124 + at2(3, 3, 4)*cs45 + cs108*cs128*cs430 + &
               cs153*cs445 + cs23*cs442 + cs23*(at2(3, 3, 1)*cs53 - at2(3, 3, 2)*cs36 - at1(3, &
               3)*cs127*cs386 + at2(3, 3, 4)*cs40 + cs23*(-cs112*cs464 + 6.0_wp*cs19*cs232*cs444 + &
               cs19*cs80*ps0(1)*ps2(3, 3, 2)*s_3 + cs19*cs80*ps1(3, 1)*ps1(3, 2)*s_3 - &
               cs227*ps2(3, 3, 4) - cs228*cs443 - cs229*ps2(3, 3, 3) - cs231*ps2(3, 3, 1)) + &
               cs348*cs459 + cs360*cs467 + cs367*cs460 + cs38*cs465 + cs42*cs462 + cs442 + &
               cs469*cs55) + cs348*(cs0*cs454 + cs0*cs455 - cs170*cs452 - cs170*cs453 + &
               cs170*cs456 + cs179*cs348 + cs23*cs459 + cs42*cs457) + cs360*(cs199*cs367 + &
               cs218*cs360 + cs23*cs467 + cs356*cs58 + cs357*cs58 + cs38*cs463 + cs454*cs58 + &
               cs55*(cs450*cs59 + cs466)) + cs367*(-cs119*cs24 - cs120*cs24 + cs191*cs359 + &
               cs192*ps0(1)*ps1(3, 1) + cs199*cs360 + cs23*cs460 - cs277*cs454 + cs55*(-cs362 - &
               cs450*cs49)) - cs372*cs426 + &
               cs38*((2.0_wp/3.0_wp)*blend_k*((1.0_wp/2.0_wp)*cs19*inv_Z*ps2(3, 3, 1)*s_3 - cs446) &
               - cs16*cs447) + cs38*((1.0_wp/3.0_wp)*at1(3, 1)*blend_k*cs463 + &
               (1.0_wp/6.0_wp)*at2(3, 3, 1)*inv_Z*s_3 + (1.0_wp/3.0_wp)*at0(2)*cs189*cs20*cs451 + &
               (1.0_wp/3.0_wp)*at1(3, 2)*cs189*cs20*ps0(1)*ps1(3, 1) - cs119*cs380 - cs120*cs380 - &
               cs210*cs450*ps1(3, 1) - cs214*cs445 + cs23*cs465 - cs437*cs454) + cs42*(cs21*cs447 &
               + cs41*(2.0_wp*cs108*cs113 - cs138*ps2(3, 3, 4))) + cs42*(-at2(3, 3, 4)*cs39 + &
               cs206*cs443 + cs208*cs445 + cs23*cs462 + cs348*cs457 + cs355*cs454 + cs355*cs455 - &
               cs452*cs461 - cs453*cs461 + cs456*cs461) + cs425*(-cs139*ps1(3, 4) + 2.0_wp*cs338) &
               + cs427*(-cs112*cs130 + cs145*cs337 + cs342) + cs430*(at1(3, 1)*cs401 + cs105*cs43 &
               + cs110*cs127 - cs123*cs127 + cs157*cs355 - cs158*cs448 - cs158*cs449 + &
               cs162*cs450) + cs55*(cs22*cs447 + cs54*(-cs131*cs451 + cs165*ps2(3, 3, 2) - &
               cs166*ps2(3, 3, 1) + cs337*cs450)) + cs55*(-at2(3, 3, 1)*cs57 + at2(3, 3, 2)*cs56 + &
               cs105*cs468 + cs112*cs356 + cs112*cs454 + cs17*cs445 + cs23*cs469 + &
               cs360*(cs116*cs145 + cs466) + cs367*(-cs361 - cs362) - cs452*cs468 + &
               cs55*(cs116*cs450 - cs131*ps2(3, 3, 1) + 2.0_wp*cs446))
         end block
      end select

   end subroutine svdw_radpair_diag_eval

   !> Mixed nuclear-radius derivative of the spatial derivatives, for A /= B.
   !>
   !> Returns `d^2/(dR_A,s dR_b) d^n S / dr^n` for n = 0..max_deriv, i.e.
   !> `f2_rA_rad`, `f3_r_rA_rad` and `f4_rr_rA_rad`: a *position* derivative on
   !> atom A and a *radius* derivative on atom B.  Index order is (spatial..., s);
   !> the radius contributes no index, so the rank is one above the spatial order.
   !>
   !> The two slots are not interchangeable.  `f{n}_rA_rad(.., s)` for the atom
   !> pair (A, B) is *not* the transpose of the same array for (B, A) -- the first
   !> asks for A's position and B's radius, the second for B's position and A's
   !> radius.  A caller that needs the full nuclear-radius block must call this routine for
   !> both orderings, and `svdw_nucrad_diag_eval` on the diagonal.
   !>
   !> This is the uncontracted form of the nuclear-radius block that
   !> `svdw_hvp_eval` and `svdw_radius_hvp_eval` already supply contracted.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    s_1          One-body blending weight blend_1b
   !> @param[in]    s_2          Two-body blending weight blend_2b
   !> @param[in]    s_3          Three-body blending weight blend_3b
   !> @param[in]    ps0          Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps1          Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps2          Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    at0          Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at1          Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at2          Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at3          Atom-A kind tensor d^3 u_A^m / dr^3 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    bt0          Atom-B kind tensor d^0 u_B^m / dr^0 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    bt1          Atom-B kind tensor d^1 u_B^m / dr^1 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    bt2          Atom-B kind tensor d^2 u_B^m / dr^2 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    max_deriv    Highest *spatial* derivative order to compute (0..2); a larger
   !>                            value is treated as 2
   !> @param[out]   f2_rA_rad    d^2S/(dR_A dR_b); trailing index is A's component
   !> @param[out]   f3_r_rA_rad  d^3S/(dr dR_A dR_b); index order (spatial, s)
   !> @param[out]   f4_rr_rA_rad d^4S/(dr^2 dR_A dR_b); index order (spatial, spatial, s)
   pure subroutine svdw_nucrad_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, at0, at1, at2, at3, &
                                    bt0, bt1, bt2, max_deriv, f2_rA_rad, f3_r_rA_rad, f4_rr_rA_rad)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at0(nkind)
      !> Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at1(3, nkind)
      !> Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at2(3, 3, nkind)
      !> Atom-A kind tensor d^3 u_A^m / dr^3 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at3(3, 3, 3, nkind)
      !> Atom-B kind tensor d^0 u_B^m / dr^0 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: bt0(nkind)
      !> Atom-B kind tensor d^1 u_B^m / dr^1 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: bt1(3, nkind)
      !> Atom-B kind tensor d^2 u_B^m / dr^2 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: bt2(3, 3, nkind)
      !> Highest *spatial* derivative order to compute (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d^2S/(dR_A dR_b); trailing index is A's component
      real(wp), intent(out) :: f2_rA_rad(3)
      !> d^3S/(dr dR_A dR_b); index order (spatial, s)
      real(wp), intent(out) :: f3_r_rA_rad(3, 3)
      !> d^4S/(dr^2 dR_A dR_b); index order (spatial, spatial, s)
      real(wp), intent(out) :: f4_rr_rA_rad(3, 3, 3)

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12

            cs0 = (1.0_wp/3.0_wp)*s_3
            cs1 = bt0(2)*cs0
            cs2 = cs1*inv_Z
            cs3 = ps0(1)*s_3
            cs4 = (1.0_wp/3.0_wp)*bt0(1)*inv_Z
            cs5 = 1.0_wp/blend_k
            cs6 = (inv_Z*inv_Z)
            cs7 = ps0(4)*s_2
            cs8 = (1.0_wp/2.0_wp)*s_2
            cs9 = cs0 - cs8 + s_1
            cs10 = s_3*(3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2))
            cs11 = (1.0_wp/6.0_wp)*cs10
            cs12 = &
               (1.0_wp/18.0_wp)*blend_k*bt0(1)*cs10 + blend_k*bt0(3)*cs9 + &
               blend_k*bt0(4)*cs8*ps0(4) - blend_k*cs1*ps0(1)
            f2_rA_rad(1) = &
               -at1(1, 1)*cs2 + (1.0_wp/2.0_wp)*at1(1, 4)*bt0(4)*inv_Z*s_2 + cs12*cs5*cs6*(-at1(1, &
               1)*cs11 + (1.0_wp/2.0_wp)*at1(1, 2)*ps0(1)*s_3 - at1(1, 3)*cs9 - at1(1, 4)*cs7) - &
               cs4*(-at1(1, 1)*cs3 + (1.0_wp/2.0_wp)*at1(1, 2)*s_3)
            f2_rA_rad(2) = &
               -at1(2, 1)*cs2 + (1.0_wp/2.0_wp)*at1(2, 4)*bt0(4)*inv_Z*s_2 + cs12*cs5*cs6*(-at1(2, &
               1)*cs11 + (1.0_wp/2.0_wp)*at1(2, 2)*ps0(1)*s_3 - at1(2, 3)*cs9 - at1(2, 4)*cs7) - &
               cs4*(-at1(2, 1)*cs3 + (1.0_wp/2.0_wp)*at1(2, 2)*s_3)
            f2_rA_rad(3) = &
               -at1(3, 1)*cs2 + (1.0_wp/2.0_wp)*at1(3, 4)*bt0(4)*inv_Z*s_2 + cs12*cs5*cs6*(-at1(3, &
               1)*cs11 + (1.0_wp/2.0_wp)*at1(3, 2)*ps0(1)*s_3 - at1(3, 3)*cs9 - at1(3, 4)*cs7) - &
               cs4*(-at1(3, 1)*cs3 + (1.0_wp/2.0_wp)*at1(3, 2)*s_3)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78
            real(wp) :: cs79, cs80, cs81, cs82, cs83, cs84, cs85, cs86, cs87, cs88, cs89, cs90, cs91
            real(wp) :: cs92, cs93, cs94, cs95, cs96, cs97, cs98, cs99, cs100, cs101, cs102, cs103
            real(wp) :: cs104, cs105, cs106

            cs0 = (1.0_wp/3.0_wp)*s_3
            cs1 = bt0(2)*cs0
            cs2 = cs1*inv_Z
            cs3 = ps0(1)*s_3
            cs4 = at1(1, 1)*cs3
            cs5 = (1.0_wp/2.0_wp)*at1(1, 2)*s_3 - cs4
            cs6 = (1.0_wp/3.0_wp)*bt0(1)
            cs7 = cs6*inv_Z
            cs8 = 1.0_wp/blend_k
            cs9 = (inv_Z*inv_Z)
            cs10 = ps0(4)*s_2
            cs11 = (1.0_wp/2.0_wp)*s_2
            cs12 = cs0 - cs11 + s_1
            cs13 = s_3*(3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2))
            cs14 = (1.0_wp/6.0_wp)*cs13
            cs15 = &
               -at1(1, 1)*cs14 + (1.0_wp/2.0_wp)*at1(1, 2)*ps0(1)*s_3 - at1(1, 3)*cs12 - at1(1, &
               4)*cs10
            cs16 = &
               (1.0_wp/18.0_wp)*blend_k*bt0(1)*cs13 + blend_k*bt0(3)*cs12 + &
               blend_k*bt0(4)*cs11*ps0(4) - blend_k*cs1*ps0(1)
            cs17 = at1(2, 1)*cs3
            cs18 = (1.0_wp/2.0_wp)*at1(2, 2)*s_3 - cs17
            cs19 = &
               -at1(2, 1)*cs14 + (1.0_wp/2.0_wp)*at1(2, 2)*ps0(1)*s_3 - at1(2, 3)*cs12 - at1(2, &
               4)*cs10
            cs20 = at1(3, 1)*cs3
            cs21 = (1.0_wp/2.0_wp)*at1(3, 2)*s_3 - cs20
            cs22 = &
               -at1(3, 1)*cs14 + (1.0_wp/2.0_wp)*at1(3, 2)*ps0(1)*s_3 - at1(3, 3)*cs12 - at1(3, &
               4)*cs10
            cs23 = cs12*cs9
            cs24 = bt1(1, 3)*cs23
            cs25 = cs8*inv_Z
            cs26 = cs25*s_2
            cs27 = cs8*cs9
            cs28 = cs10*cs27
            cs29 = at1(1, 4)*cs26 + cs15*cs28
            cs30 = (1.0_wp/2.0_wp)*blend_k
            cs31 = bt1(1, 4)*cs30
            cs32 = (1.0_wp/2.0_wp)*s_3
            cs33 = cs25*cs32
            cs34 = cs27*cs32
            cs35 = cs34*ps0(1)
            cs36 = -at1(1, 1)*cs33 - cs15*cs35
            cs37 = (2.0_wp/3.0_wp)*blend_k
            cs38 = bt1(1, 2)*cs37
            cs39 = cs14*cs27
            cs40 = -at1(1, 2)*cs25*cs32 + cs15*cs39 + cs25*cs4
            cs41 = (1.0_wp/3.0_wp)*blend_k
            cs42 = bt1(1, 1)*cs41
            cs43 = cs32*ps1(1, 2)
            cs44 = cs10*ps1(1, 4) + cs12*ps1(1, 3) + cs14*ps1(1, 1) - cs43*ps0(1)
            cs45 = cs27*cs44
            cs46 = at1(1, 4)*s_2
            cs47 = cs27*ps1(1, 4)
            cs48 = cs47*s_2
            cs49 = bt0(4)*cs30
            cs50 = cs27*cs32*ps1(1, 1)
            cs51 = bt0(2)*cs37
            cs52 = cs25*s_3
            cs53 = cs52*ps1(1, 1)
            cs54 = cs25*cs3
            cs55 = cs27*(cs3*ps1(1, 1) - cs43)
            cs56 = blend_k*cs6
            cs57 = cs12*cs27
            cs58 = 2.0_wp*cs8*(inv_Z*inv_Z*inv_Z)
            cs59 = cs44*cs58
            cs60 = at1(2, 4)*cs26 + cs19*cs28
            cs61 = -at1(2, 1)*cs33 - cs19*cs35
            cs62 = -at1(2, 2)*cs25*cs32 + cs17*cs25 + cs19*cs39
            cs63 = at2(1, 2, 4)*cs26
            cs64 = cs45*s_2
            cs65 = at2(1, 2, 1)*cs33
            cs66 = at2(1, 2, 1)*cs54 - at2(1, 2, 2)*cs33
            cs67 = &
               at2(1, 2, 1)*cs39 - 1.0_wp/2.0_wp*at2(1, 2, 2)*cs8*cs9*ps0(1)*s_3 + at2(1, 2, &
               3)*cs57 + at2(1, 2, 4)*cs28
            cs68 = at1(3, 4)*cs26 + cs22*cs28
            cs69 = -at1(3, 1)*cs33 - cs22*cs35
            cs70 = -at1(3, 2)*cs25*cs32 + cs20*cs25 + cs22*cs39
            cs71 = at2(1, 3, 4)*cs26
            cs72 = at2(1, 3, 1)*cs33
            cs73 = at2(1, 3, 1)*cs54 - at2(1, 3, 2)*cs33
            cs74 = &
               at2(1, 3, 1)*cs39 - 1.0_wp/2.0_wp*at2(1, 3, 2)*cs8*cs9*ps0(1)*s_3 + at2(1, 3, &
               3)*cs57 + at2(1, 3, 4)*cs28
            cs75 = bt1(2, 3)*cs23
            cs76 = bt1(2, 4)*cs30
            cs77 = bt1(2, 2)*cs37
            cs78 = bt1(2, 1)*cs41
            cs79 = cs32*ps1(2, 2)
            cs80 = cs10*ps1(2, 4) + cs12*ps1(2, 3) + cs14*ps1(2, 1) - cs79*ps0(1)
            cs81 = cs27*cs80
            cs82 = cs27*ps1(2, 4)
            cs83 = cs82*s_2
            cs84 = cs34*ps1(2, 1)
            cs85 = cs27*(cs3*ps1(2, 1) - cs79)
            cs86 = cs52*ps1(2, 1)
            cs87 = cs58*cs80
            cs88 = cs81*s_2
            cs89 = at2(2, 3, 4)*cs26
            cs90 = at2(2, 3, 1)*cs33
            cs91 = at2(2, 3, 1)*cs54 - at2(2, 3, 2)*cs33
            cs92 = &
               at2(2, 3, 1)*cs39 - 1.0_wp/2.0_wp*at2(2, 3, 2)*cs8*cs9*ps0(1)*s_3 + at2(2, 3, &
               3)*cs57 + at2(2, 3, 4)*cs28
            cs93 = bt1(3, 3)*cs23
            cs94 = bt1(3, 4)*cs30
            cs95 = bt1(3, 2)*cs37
            cs96 = bt1(3, 1)*cs41
            cs97 = cs32*ps1(3, 2)
            cs98 = cs10*ps1(3, 4) + cs12*ps1(3, 3) + cs14*ps1(3, 1) - cs97*ps0(1)
            cs99 = cs27*cs98
            cs100 = cs27*ps1(3, 4)
            cs101 = cs100*s_2
            cs102 = cs34*ps1(3, 1)
            cs103 = cs27*(cs3*ps1(3, 1) - cs97)
            cs104 = cs52*ps1(3, 1)
            cs105 = cs58*cs98
            cs106 = cs99*s_2
            f2_rA_rad(1) = &
               -at1(1, 1)*cs2 + (1.0_wp/2.0_wp)*at1(1, 4)*bt0(4)*inv_Z*s_2 + cs15*cs16*cs8*cs9 - &
               cs5*cs7
            f2_rA_rad(2) = &
               -at1(2, 1)*cs2 + (1.0_wp/2.0_wp)*at1(2, 4)*bt0(4)*inv_Z*s_2 + cs16*cs19*cs8*cs9 - &
               cs18*cs7
            f2_rA_rad(3) = &
               -at1(3, 1)*cs2 + (1.0_wp/2.0_wp)*at1(3, 4)*bt0(4)*inv_Z*s_2 + cs16*cs22*cs8*cs9 - &
