               + at1(3, 2)*cs141*cs8*cs9*ps1(3, 1)*s_3 - at2(3, 3, 2)*cs586 - at3(3, 3, 3, 2)*cs35 &
               - at2(3, 3, 3)*cs588 - 2.0_wp*at2(3, 3, 4)*cs447 + cs23*cs572 + cs24*cs587 - &
               cs589*cs596)
         end block
      end select

   end subroutine svdw_nucrad_eval

   !> Mixed nuclear-radius derivative of the spatial derivatives, for A == B.
   !>
   !> Same outputs and index order as `svdw_nucrad_eval`, but with the position and
   !> the radius belonging to the *same* atom, so `d/dR_a` still sees atom A's own
   !> tensors instead of annihilating them.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    s_1          One-body blending weight blend_1b
   !> @param[in]    s_2          Two-body blending weight blend_2b
   !> @param[in]    s_3          Three-body blending weight blend_3b
   !> @param[in]    ps0          Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps1          Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps2          Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    at0          Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at1          Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at2          Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at3          Atom-A kind tensor d^3 u_A^m / dr^3 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    max_deriv    Highest *spatial* derivative order to compute (0..2); a larger
   !>                            value is treated as 2
   !> @param[out]   f2_rA_rad    d^2S/(dR_A dR_b); trailing index is A's component
   !> @param[out]   f3_r_rA_rad  d^3S/(dr dR_A dR_b); index order (spatial, s)
   !> @param[out]   f4_rr_rA_rad d^4S/(dr^2 dR_A dR_b); index order (spatial, spatial, s)
   pure subroutine svdw_nucrad_diag_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, at0, at1, at2, &
                                         at3, max_deriv, f2_rA_rad, f3_r_rA_rad, f4_rr_rA_rad)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at0(nkind)
      !> Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at1(3, nkind)
      !> Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at2(3, 3, nkind)
      !> Atom-A kind tensor d^3 u_A^m / dr^3 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at3(3, 3, 3, nkind)
      !> Highest *spatial* derivative order to compute (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d^2S/(dR_A dR_b); trailing index is A's component
      real(wp), intent(out) :: f2_rA_rad(3)
      !> d^3S/(dr dR_A dR_b); index order (spatial, s)
      real(wp), intent(out) :: f3_r_rA_rad(3, 3)
      !> d^4S/(dr^2 dR_A dR_b); index order (spatial, spatial, s)
      real(wp), intent(out) :: f4_rr_rA_rad(3, 3, 3)

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13

            cs0 = (1.0_wp/3.0_wp)*s_3
            cs1 = at0(2)*cs0
            cs2 = cs0*inv_Z*ps0(1)
            cs3 = cs0 + s_1 - 1.0_wp/2.0_wp*s_2
            cs4 = -cs3*inv_Z
            cs5 = ps0(1)*s_3
            cs6 = (1.0_wp/3.0_wp)*at0(1)*inv_Z
            cs7 = 3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2)
            cs8 = 1.0_wp/blend_k
            cs9 = (inv_Z*inv_Z)
            cs10 = ps0(4)*s_2
            cs11 = cs7*s_3
            cs12 = (1.0_wp/6.0_wp)*cs11
            cs13 = &
               (1.0_wp/18.0_wp)*at0(1)*blend_k*cs11 + at0(3)*blend_k*cs3 + &
               (1.0_wp/2.0_wp)*at0(4)*blend_k*ps0(4)*s_2 - blend_k*cs1*ps0(1)
            f2_rA_rad(1) = &
               -at1(1, 1)*cs1*inv_Z + (1.0_wp/18.0_wp)*at1(1, 1)*cs7*inv_Z*s_3 - at1(1, 2)*cs2 - &
               at1(1, 3)*cs4 + (1.0_wp/2.0_wp)*at0(4)*at1(1, 4)*inv_Z*s_2 + (1.0_wp/2.0_wp)*at1(1, &
               4)*inv_Z*ps0(4)*s_2 + cs13*cs8*cs9*(-at1(1, 1)*cs12 + (1.0_wp/2.0_wp)*at1(1, &
               2)*ps0(1)*s_3 - at1(1, 3)*cs3 - at1(1, 4)*cs10) - cs6*(-at1(1, 1)*cs5 + &
               (1.0_wp/2.0_wp)*at1(1, 2)*s_3)
            f2_rA_rad(2) = &
               -at1(2, 1)*cs1*inv_Z + (1.0_wp/18.0_wp)*at1(2, 1)*cs7*inv_Z*s_3 - at1(2, 2)*cs2 - &
               at1(2, 3)*cs4 + (1.0_wp/2.0_wp)*at0(4)*at1(2, 4)*inv_Z*s_2 + (1.0_wp/2.0_wp)*at1(2, &
               4)*inv_Z*ps0(4)*s_2 + cs13*cs8*cs9*(-at1(2, 1)*cs12 + (1.0_wp/2.0_wp)*at1(2, &
               2)*ps0(1)*s_3 - at1(2, 3)*cs3 - at1(2, 4)*cs10) - cs6*(-at1(2, 1)*cs5 + &
               (1.0_wp/2.0_wp)*at1(2, 2)*s_3)
            f2_rA_rad(3) = &
               -at1(3, 1)*cs1*inv_Z + (1.0_wp/18.0_wp)*at1(3, 1)*cs7*inv_Z*s_3 - at1(3, 2)*cs2 - &
               at1(3, 3)*cs4 + (1.0_wp/2.0_wp)*at0(4)*at1(3, 4)*inv_Z*s_2 + (1.0_wp/2.0_wp)*at1(3, &
               4)*inv_Z*ps0(4)*s_2 + cs13*cs8*cs9*(-at1(3, 1)*cs12 + (1.0_wp/2.0_wp)*at1(3, &
               2)*ps0(1)*s_3 - at1(3, 3)*cs3 - at1(3, 4)*cs10) - cs6*(-at1(3, 1)*cs5 + &
               (1.0_wp/2.0_wp)*at1(3, 2)*s_3)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78
            real(wp) :: cs79, cs80, cs81, cs82, cs83, cs84, cs85, cs86, cs87, cs88, cs89, cs90, cs91
            real(wp) :: cs92, cs93, cs94, cs95, cs96, cs97, cs98, cs99, cs100, cs101, cs102, cs103
            real(wp) :: cs104, cs105, cs106, cs107, cs108, cs109, cs110, cs111, cs112, cs113, cs114
            real(wp) :: cs115, cs116, cs117, cs118, cs119, cs120, cs121, cs122, cs123, cs124, cs125
            real(wp) :: cs126, cs127, cs128, cs129, cs130, cs131, cs132, cs133, cs134, cs135, cs136
            real(wp) :: cs137

            cs0 = (1.0_wp/3.0_wp)*s_3
            cs1 = at0(2)*cs0
            cs2 = cs0*inv_Z*ps0(1)
            cs3 = cs0 + s_1 - 1.0_wp/2.0_wp*s_2
            cs4 = -cs3
            cs5 = cs4*inv_Z
            cs6 = ps0(1)*s_3
            cs7 = at1(1, 1)*cs6
            cs8 = (1.0_wp/2.0_wp)*at1(1, 2)*s_3 - cs7
            cs9 = (1.0_wp/3.0_wp)*at0(1)
            cs10 = cs9*inv_Z
            cs11 = 3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2)
            cs12 = 1.0_wp/blend_k
            cs13 = (inv_Z*inv_Z)
            cs14 = ps0(4)*s_2
            cs15 = at1(1, 3)*cs3
            cs16 = cs11*s_3
            cs17 = (1.0_wp/6.0_wp)*cs16
            cs18 = -at1(1, 1)*cs17 + (1.0_wp/2.0_wp)*at1(1, 2)*ps0(1)*s_3 - at1(1, 4)*cs14 - cs15
            cs19 = (1.0_wp/2.0_wp)*s_2
            cs20 = (1.0_wp/18.0_wp)*cs16
            cs21 = &
               at0(1)*blend_k*cs20 + at0(3)*blend_k*cs3 + at0(4)*blend_k*cs19*ps0(4) - &
               blend_k*cs1*ps0(1)
            cs22 = at1(2, 1)*cs6
            cs23 = (1.0_wp/2.0_wp)*at1(2, 2)*s_3 - cs22
            cs24 = at1(2, 3)*cs3
            cs25 = -at1(2, 1)*cs17 + (1.0_wp/2.0_wp)*at1(2, 2)*ps0(1)*s_3 - at1(2, 4)*cs14 - cs24
            cs26 = at1(3, 1)*cs6
            cs27 = (1.0_wp/2.0_wp)*at1(3, 2)*s_3 - cs26
            cs28 = at1(3, 3)*cs3
            cs29 = -at1(3, 1)*cs17 + (1.0_wp/2.0_wp)*at1(3, 2)*ps0(1)*s_3 - at1(3, 4)*cs14 - cs28
            cs30 = cs19*inv_Z*ps0(4)
            cs31 = cs3*inv_Z
            cs32 = cs20*inv_Z
            cs33 = (1.0_wp/2.0_wp)*s_3
            cs34 = cs33*ps1(1, 2)
            cs35 = cs14*ps1(1, 4) + cs17*ps1(1, 1) + cs3*ps1(1, 3) - cs34*ps0(1)
            cs36 = cs13*cs4
            cs37 = cs35*cs36
            cs38 = cs13*cs15
            cs39 = cs12*cs13
            cs40 = cs35*cs39
            cs41 = cs12*inv_Z*ps1(1, 4)*s_2 - cs14*cs40
            cs42 = (1.0_wp/2.0_wp)*blend_k
            cs43 = at1(1, 4)*cs42
            cs44 = cs12*inv_Z
            cs45 = cs33*cs44
            cs46 = cs33*ps0(1)
            cs47 = cs40*cs46 - cs45*ps1(1, 1)
            cs48 = (2.0_wp/3.0_wp)*blend_k
            cs49 = at1(1, 2)*cs48
            cs50 = cs44*s_2
            cs51 = cs14*cs39
            cs52 = at1(1, 4)*cs50 + cs18*cs51
            cs53 = cs39*cs46
            cs54 = -at1(1, 1)*cs45 - cs18*cs53
            cs55 = -cs34 + cs6*ps1(1, 1)
            cs56 = cs12*cs55*inv_Z - cs17*cs40
            cs57 = (1.0_wp/3.0_wp)*blend_k
            cs58 = at1(1, 1)*cs57
            cs59 = cs17*cs39
            cs60 = -at1(1, 2)*cs33*cs44 + cs18*cs59 + cs44*cs7
            cs61 = at1(1, 4)*s_2
            cs62 = cs39*ps1(1, 4)
            cs63 = cs62*s_2
            cs64 = at0(4)*cs42
            cs65 = cs33*cs39*ps1(1, 1)
            cs66 = at0(2)*cs48
            cs67 = cs44*s_3
            cs68 = cs67*ps1(1, 1)
            cs69 = cs44*cs6
            cs70 = cs39*cs55
            cs71 = blend_k*cs9
            cs72 = cs3*cs39
            cs73 = 2.0_wp*cs12*(inv_Z*inv_Z*inv_Z)
            cs74 = cs35*cs73
            cs75 = &
               at2(1, 2, 1)*cs59 - 1.0_wp/2.0_wp*at2(1, 2, 2)*cs12*cs13*ps0(1)*s_3 + at2(1, 2, &
               3)*cs72 + at2(1, 2, 4)*cs51
            cs76 = at2(1, 2, 4)*cs50
            cs77 = cs40*s_2
            cs78 = at1(2, 4)*cs50 + cs25*cs51
            cs79 = cs41*cs42
            cs80 = at2(1, 2, 1)*cs69 - at2(1, 2, 2)*cs45
            cs81 = -at1(2, 2)*cs33*cs44 + cs22*cs44 + cs25*cs59
            cs82 = cs56*cs57
            cs83 = at2(1, 2, 1)*cs45
            cs84 = -at1(2, 1)*cs45 - cs25*cs53
            cs85 = cs47*cs48
            cs86 = at2(1, 2, 1)*cs32 - at2(1, 2, 2)*cs2 + at2(1, 2, 3)*cs31 + at2(1, 2, 4)*cs30
            cs87 = &
               at2(1, 3, 1)*cs59 - 1.0_wp/2.0_wp*at2(1, 3, 2)*cs12*cs13*ps0(1)*s_3 + at2(1, 3, &
               3)*cs72 + at2(1, 3, 4)*cs51
            cs88 = at2(1, 3, 4)*cs50
            cs89 = at1(3, 4)*cs50 + cs29*cs51
            cs90 = at2(1, 3, 1)*cs69 - at2(1, 3, 2)*cs45
            cs91 = -at1(3, 2)*cs33*cs44 + cs26*cs44 + cs29*cs59
            cs92 = at2(1, 3, 1)*cs45
            cs93 = -at1(3, 1)*cs45 - cs29*cs53
            cs94 = at2(1, 3, 1)*cs32 - at2(1, 3, 2)*cs2 + at2(1, 3, 3)*cs31 + at2(1, 3, 4)*cs30
            cs95 = cs33*ps1(2, 2)
            cs96 = cs6*ps1(2, 1) - cs95
            cs97 = cs39*cs96
            cs98 = cs14*ps1(2, 4) + cs17*ps1(2, 1) + cs3*ps1(2, 3) - cs95*ps0(1)
            cs99 = cs73*cs98
            cs100 = cs39*ps1(2, 4)
            cs101 = cs39*cs98
            cs102 = cs100*s_2
            cs103 = -cs101*cs14 + cs12*inv_Z*ps1(2, 4)*s_2
            cs104 = at1(2, 4)*cs42
            cs105 = cs67*ps1(2, 1)
            cs106 = -cs101*cs17 + cs12*cs96*inv_Z
            cs107 = at1(2, 1)*cs57
            cs108 = cs33*cs39*ps1(2, 1)
            cs109 = cs101*cs46 - cs45*ps1(2, 1)
            cs110 = at1(2, 2)*cs48
            cs111 = cs36*cs98
            cs112 = cs13*cs24
            cs113 = cs101*s_2
            cs114 = &
               at2(2, 3, 1)*cs59 - 1.0_wp/2.0_wp*at2(2, 3, 2)*cs12*cs13*ps0(1)*s_3 + at2(2, 3, &
               3)*cs72 + at2(2, 3, 4)*cs51
            cs115 = at2(2, 3, 4)*cs50
            cs116 = at1(3, 4)*cs42
            cs117 = at2(2, 3, 1)*cs69 - at2(2, 3, 2)*cs45
            cs118 = at1(3, 1)*cs57
            cs119 = at2(2, 3, 1)*cs45
            cs120 = at1(3, 2)*cs48
            cs121 = at2(2, 3, 1)*cs32 - at2(2, 3, 2)*cs2 + at2(2, 3, 3)*cs31 + at2(2, 3, 4)*cs30
            cs122 = cs33*ps1(3, 2)
            cs123 = -cs122 + cs6*ps1(3, 1)
            cs124 = cs123*cs39
            cs125 = -cs122*ps0(1) + cs14*ps1(3, 4) + cs17*ps1(3, 1) + cs3*ps1(3, 3)
            cs126 = cs125*cs73
            cs127 = cs39*ps1(3, 4)
            cs128 = cs125*cs39
            cs129 = cs127*s_2
            cs130 = cs12*inv_Z*ps1(3, 4)*s_2 - cs128*cs14
            cs131 = cs67*ps1(3, 1)
            cs132 = cs12*cs123*inv_Z - cs128*cs17
            cs133 = cs33*cs39*ps1(3, 1)
            cs134 = cs128*cs46 - cs45*ps1(3, 1)
            cs135 = cs125*cs36
            cs136 = cs13*cs28
            cs137 = cs128*s_2
            f2_rA_rad(1) = &
               -at1(1, 1)*cs1*inv_Z + (1.0_wp/18.0_wp)*at1(1, 1)*cs11*inv_Z*s_3 - at1(1, 2)*cs2 - &
               at1(1, 3)*cs5 + (1.0_wp/2.0_wp)*at0(4)*at1(1, 4)*inv_Z*s_2 + (1.0_wp/2.0_wp)*at1(1, &
               4)*inv_Z*ps0(4)*s_2 - cs10*cs8 + cs12*cs13*cs18*cs21
            f2_rA_rad(2) = &
               -at1(2, 1)*cs1*inv_Z + (1.0_wp/18.0_wp)*at1(2, 1)*cs11*inv_Z*s_3 - at1(2, 2)*cs2 - &
               at1(2, 3)*cs5 + (1.0_wp/2.0_wp)*at0(4)*at1(2, 4)*inv_Z*s_2 + (1.0_wp/2.0_wp)*at1(2, &
               4)*inv_Z*ps0(4)*s_2 - cs10*cs23 + cs12*cs13*cs21*cs25
            f2_rA_rad(3) = &
               -at1(3, 1)*cs1*inv_Z + (1.0_wp/18.0_wp)*at1(3, 1)*cs11*inv_Z*s_3 - at1(3, 2)*cs2 - &
               at1(3, 3)*cs5 + (1.0_wp/2.0_wp)*at0(4)*at1(3, 4)*inv_Z*s_2 + (1.0_wp/2.0_wp)*at1(3, &
               4)*inv_Z*ps0(4)*s_2 - cs10*cs27 + cs12*cs13*cs21*cs29
            f3_r_rA_rad(1, 1) = &
               at2(1, 1, 1)*cs32 - at2(1, 1, 2)*cs2 + at1(1, 3)*cs37 + at2(1, 1, 3)*cs31 + at2(1, &
               1, 4)*cs30 + cs18*cs38 + cs21*(-at1(1, 1)*cs70 - at2(1, 1, 1)*cs59 + &
               (1.0_wp/2.0_wp)*at1(1, 2)*cs12*cs13*ps1(1, 1)*s_3 + (1.0_wp/2.0_wp)*at2(1, 1, &
               2)*cs12*cs13*ps0(1)*s_3 - at2(1, 1, 3)*cs72 - at2(1, 1, 4)*cs51 - cs18*cs74 - &
               cs61*cs62) + cs41*cs43 + cs43*cs52 + cs47*cs49 + cs49*cs54 + cs56*cs58 + cs58*cs60 &
               + cs64*(at2(1, 1, 4)*cs50 + cs18*cs63 - cs40*cs61) + cs66*((1.0_wp/2.0_wp)*at1(1, &
               1)*cs12*cs13*cs35*s_3 - at2(1, 1, 1)*cs45 - cs18*cs65) + cs71*(at1(1, 1)*cs68 + &
               at2(1, 1, 1)*cs69 - at2(1, 1, 2)*cs45 + cs18*cs70 + cs40*cs8)
            f3_r_rA_rad(1, 2) = &
               at1(2, 1)*cs82 + at1(2, 2)*cs85 + at1(2, 3)*cs37 + at1(2, 4)*cs79 + cs21*(-at1(2, &
               1)*cs70 + (1.0_wp/2.0_wp)*at1(2, 2)*cs12*cs13*ps1(1, 1)*s_3 - at1(2, 4)*cs63 - &
               cs25*cs74 - cs75) + cs25*cs38 + cs43*cs78 + cs49*cs84 + cs58*cs81 + cs64*(-at1(2, &
               4)*cs77 + cs25*cs63 + cs76) + cs66*((1.0_wp/2.0_wp)*at1(2, 1)*cs12*cs13*cs35*s_3 - &
               cs25*cs65 - cs83) + cs71*(at1(2, 1)*cs68 + cs23*cs40 + cs25*cs70 + cs80) + cs86
