               cs22*ps2(3, 3, 1)) + ps2(3, 3, 1)*(cs128*cs65 + cs484) + ps2(3, 3, 2)*(-cs1*cs128 - &
               cs182)) + ws1(3, 1)*(cs190 + cs193*cs65 + cs195*cs65 + cs200*cs9 + cs243*ps2(3, 3, &
               2) + cs256*ps2(3, 3, 1) + cs39*cs486 + cs474*cs78 + cs479*ps1(3, 2) + ps1(3, &
               1)*(cs189*cs78 + cs484)) + ws2(3, 3, 1)*(cs125*cs7 + cs192 + cs389) + &
               ws0(2)*((1.0_wp/2.0_wp)*cs11*cs187*cs225*cs24*ps1(3, 2) + &
               (1.0_wp/2.0_wp)*cs11*cs225*cs24*ps0(1)*ps1(3, 1)*ps2(3, 3, 2) + &
               (1.0_wp/2.0_wp)*cs11*inv_Z*ps3(3, 3, 3, 1)*s_3 - cs167*cs200 - &
               1.0_wp/2.0_wp*cs187*cs189*cs222 - cs195*cs421 + cs39*cs480 - cs391*cs405 - &
               cs406*cs474 + cs479*ps2(3, 3, 1)) + ws1(3, 2)*(-cs1*cs193 - cs1*cs195 - cs183 - &
               cs2*cs200 + cs242*ps2(3, 3, 2) + cs243*ps2(3, 3, 1) + cs39*cs482 + cs419*ps0(1) - &
               cs474*cs72 + cs58*ps2(3, 3, 1) + ps1(3, 1)*(-cs182 - cs189*cs72)) + ws2(3, 3, &
               2)*((3.0_wp/2.0_wp)*cs11*inv_Z*ps1(3, 1)*s_3 - 3.0_wp/2.0_wp*cs179) + ws1(3, &
               3)*(cs189*cs394 + cs196*cs42 - cs199*cs42 + cs200*cs5 + cs206*ps2(3, 3, 1) - &
               cs269*ps2(3, 3, 2) - cs34*cs394 + 2.0_wp*cs392 + 2.0_wp*cs393) + ws2(3, 3, &
               3)*(cs115 + cs177) + ws0(4)*(cs123*cs200 - cs131*cs396 - cs131*cs472 + cs131*cs473 &
               + cs131*cs474 + cs131*cs475 - cs14*ps3(3, 3, 3, 4) + cs210*(ps1(3, 4)*ps1(3, &
               4)*ps1(3, 4)) + cs39*cs478 + cs476*ps2(3, 3, 4)) + ws1(3, 4)*(cs0*cs200 + cs185 + &
               cs235*ps2(3, 3, 4) + cs39*cs481 - cs396*cs67 - cs472*cs67 + cs473*cs67 + cs474*cs67 &
               + cs475*cs67 + cs476*ps1(3, 4)) + ws2(3, 3, 4)*(3.0_wp*cs117 - 3.0_wp*cs33)
         end block
      end select

   end subroutine svdw_tangent_eval

   !> Nuclear Hessian-vector product of the spatial derivatives, for one atom A.
   !>
   !> Given one displacement direction v_B per atom, returns
   !>
   !>    hvp_f{n+1}(i1..in, s) = sum_B sum_alpha v_B,alpha
   !>                            d^2/(dR_A,s dR_B,alpha) d^n S / dr_i1..dr_in
   !>
   !> for n = 0..max_deriv: exactly one of the two nuclear indices is contracted,
   !> the other is retained as the trailing index.  These are derivatives of `S`
   !> itself, with the log lift already applied.
   !>
   !> One call per active atom turns what would be an O(n_active^2) tensor into
   !> O(n_active) storage and O(n_active) work.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    s_1          One-body blending weight blend_1b
   !> @param[in]    s_2          Two-body blending weight blend_2b
   !> @param[in]    s_3          Three-body blending weight blend_3b
   !> @param[in]    ps0          Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps1          Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps2          Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ws0          Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the
   !>                            order-0 power-sum tensor; last index selects the kind
   !> @param[in]    ws1          Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the
   !>                            order-1 power-sum tensor; last index selects the kind
   !> @param[in]    ws2          Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the
   !>                            order-2 power-sum tensor; last index selects the kind
   !> @param[in]    at0          Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at1          Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at2          Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at3          Atom-A kind tensor d^3 u_A^m / dr^3 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    aw0          Atom-A direction-contracted kind tensor from
   !>                            svdw_atom_tangent_eval; last index selects the kind
   !> @param[in]    aw1          Atom-A direction-contracted kind tensor from
   !>                            svdw_atom_tangent_eval; last index selects the kind
   !> @param[in]    aw2          Atom-A direction-contracted kind tensor from
   !>                            svdw_atom_tangent_eval; last index selects the kind
   !> @param[in]    aw3          Atom-A direction-contracted kind tensor from
   !>                            svdw_atom_tangent_eval; last index selects the kind
   !> @param[in]    max_deriv    Highest spatial-derivative order to compute (0..2); a larger value
   !>                            is treated as 2
   !> @param[out]   hvp_f1_rA    sum_B v_B . d^2S/(dR_A dR_B); trailing index is A's component
   !> @param[out]   hvp_f2_r_rA  sum_B v_B . d^3S/(dr dR_A dR_B); trailing index is A's component
   !> @param[out]   hvp_f3_rr_rA sum_B v_B . d^4S/(dr^2 dR_A dR_B); trailing index is A's component
   pure subroutine svdw_hvp_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, ws0, ws1, ws2, at0, at1, &
                                 at2, at3, aw0, aw1, aw2, aw3, max_deriv, hvp_f1_rA, hvp_f2_r_rA, &
                                 hvp_f3_rr_rA)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the order-0 power-sum tensor;
      !> last index selects the kind
      real(wp), intent(in) :: ws0(nkind)
      !> Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the order-1 power-sum tensor;
      !> last index selects the kind
      real(wp), intent(in) :: ws1(3, nkind)
      !> Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the order-2 power-sum tensor;
      !> last index selects the kind
      real(wp), intent(in) :: ws2(3, 3, nkind)
      !> Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at0(nkind)
      !> Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at1(3, nkind)
      !> Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at2(3, 3, nkind)
      !> Atom-A kind tensor d^3 u_A^m / dr^3 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at3(3, 3, 3, nkind)
      !> Atom-A direction-contracted kind tensor from svdw_atom_tangent_eval; last index selects the
      !> kind
      real(wp), intent(in) :: aw0(nkind)
      !> Atom-A direction-contracted kind tensor from svdw_atom_tangent_eval; last index selects the
      !> kind
      real(wp), intent(in) :: aw1(3, nkind)
      !> Atom-A direction-contracted kind tensor from svdw_atom_tangent_eval; last index selects the
      !> kind
      real(wp), intent(in) :: aw2(3, 3, nkind)
      !> Atom-A direction-contracted kind tensor from svdw_atom_tangent_eval; last index selects the
      !> kind
      real(wp), intent(in) :: aw3(3, 3, 3, nkind)
      !> Highest spatial-derivative order to compute (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> sum_B v_B . d^2S/(dR_A dR_B); trailing index is A's component
      real(wp), intent(out) :: hvp_f1_rA(3)
      !> sum_B v_B . d^3S/(dr dR_A dR_B); trailing index is A's component
      real(wp), intent(out) :: hvp_f2_r_rA(3, 3)
      !> sum_B v_B . d^4S/(dr^2 dR_A dR_B); trailing index is A's component
      real(wp), intent(out) :: hvp_f3_rr_rA(3, 3, 3)

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16

            cs0 = 1.0_wp/blend_k
            cs1 = cs0*inv_Z
            cs2 = cs1*s_2*ws0(4)
            cs3 = ps0(4)*s_2
            cs4 = cs1*cs3
            cs5 = (1.0_wp/2.0_wp)*s_3
            cs6 = cs1*cs5*ws0(1)
            cs7 = cs1*cs5*ps0(1)
            cs8 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
            cs9 = cs1*cs8
            cs10 = cs5*ws0(2)
            cs11 = s_3*ws0(1)
            cs12 = cs1*(-cs10 + cs11*ps0(1))
            cs13 = (1.0_wp/2.0_wp)*(ps0(1)*ps0(1)) - 1.0_wp/2.0_wp*ps0(2)
            cs14 = cs13*s_3
            cs15 = cs1*cs14
            cs16 = cs0*(inv_Z*inv_Z)*(-cs10*ps0(1) + cs11*cs13 + cs3*ws0(4) + cs8*ws0(3))
            hvp_f1_rA(1) = &
               at1(1, 1)*cs12 - at1(1, 2)*cs6 + at1(1, 4)*cs2 + aw1(1, 1)*cs15 - aw1(1, 2)*cs7 + &
               aw1(1, 3)*cs9 + aw1(1, 4)*cs4 + cs16*(-at1(1, 1)*cs14 + (1.0_wp/2.0_wp)*at1(1, &
               2)*ps0(1)*s_3 - at1(1, 3)*cs8 - at1(1, 4)*cs3)
            hvp_f1_rA(2) = &
               at1(2, 1)*cs12 - at1(2, 2)*cs6 + at1(2, 4)*cs2 + aw1(2, 1)*cs15 - aw1(2, 2)*cs7 + &
               aw1(2, 3)*cs9 + aw1(2, 4)*cs4 + cs16*(-at1(2, 1)*cs14 + (1.0_wp/2.0_wp)*at1(2, &
               2)*ps0(1)*s_3 - at1(2, 3)*cs8 - at1(2, 4)*cs3)
            hvp_f1_rA(3) = &
               at1(3, 1)*cs12 - at1(3, 2)*cs6 + at1(3, 4)*cs2 + aw1(3, 1)*cs15 - aw1(3, 2)*cs7 + &
               aw1(3, 3)*cs9 + aw1(3, 4)*cs4 + cs16*(-at1(3, 1)*cs14 + (1.0_wp/2.0_wp)*at1(3, &
               2)*ps0(1)*s_3 - at1(3, 3)*cs8 - at1(3, 4)*cs3)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78
            real(wp) :: cs79, cs80, cs81, cs82, cs83, cs84

            cs0 = 1.0_wp/blend_k
            cs1 = cs0*inv_Z
            cs2 = cs1*s_2
            cs3 = cs2*ws0(4)
            cs4 = ps0(4)*s_2
            cs5 = cs1*cs4
            cs6 = (1.0_wp/2.0_wp)*s_3
            cs7 = cs1*cs6
            cs8 = cs7*ws0(1)
            cs9 = cs6*ps0(1)
            cs10 = cs1*cs9
            cs11 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
            cs12 = cs1*cs11
            cs13 = cs6*ws0(2)
            cs14 = ps0(1)*s_3
            cs15 = cs14*ws0(1)
            cs16 = -cs13 + cs15
            cs17 = cs1*cs16
            cs18 = 3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2)
            cs19 = (1.0_wp/6.0_wp)*cs18
            cs20 = cs19*s_3
            cs21 = cs1*cs20
            cs22 = &
               -at1(1, 1)*cs20 + (1.0_wp/2.0_wp)*at1(1, 2)*ps0(1)*s_3 - at1(1, 3)*cs11 - at1(1, &
               4)*cs4
            cs23 = s_3*ws0(1)
            cs24 = cs11*ws0(3) - cs13*ps0(1) + cs19*cs23 + cs4*ws0(4)
            cs25 = cs0*(inv_Z*inv_Z)
            cs26 = cs24*cs25
            cs27 = &
               -at1(2, 1)*cs20 + (1.0_wp/2.0_wp)*at1(2, 2)*ps0(1)*s_3 - at1(2, 3)*cs11 - at1(2, &
               4)*cs4
            cs28 = &
               -at1(3, 1)*cs20 + (1.0_wp/2.0_wp)*at1(3, 2)*ps0(1)*s_3 - at1(3, 3)*cs11 - at1(3, &
               4)*cs4
            cs29 = cs11*cs26
            cs30 = cs6*ps1(1, 2)
            cs31 = cs11*ps1(1, 3) + cs20*ps1(1, 1) - cs30*ps0(1) + cs4*ps1(1, 4)
            cs32 = cs11*cs25
            cs33 = cs31*cs32
            cs34 = cs26*cs4 - cs3
            cs35 = cs25*cs4
            cs36 = -cs2*ps1(1, 4) + cs31*cs35
            cs37 = (1.0_wp/2.0_wp)*cs0*inv_Z*s_3*ws0(1) - cs26*cs9
            cs38 = cs25*cs9
            cs39 = (1.0_wp/2.0_wp)*cs0*inv_Z*ps1(1, 1)*s_3 - cs31*cs38
            cs40 = cs14*ps1(1, 1) - cs30
            cs41 = cs20*cs25
            cs42 = -cs1*cs40 + cs31*cs41
            cs43 = cs1*cs13 - cs1*cs15 + cs20*cs26
            cs44 = ps1(1, 4)*s_2
            cs45 = cs25*ws0(4)
            cs46 = cs45*s_2
            cs47 = -cs2*ws1(1, 4) + cs26*cs44 + cs31*cs46
            cs48 = cs26*cs6
            cs49 = cs25*ws0(1)
            cs50 = cs49*cs6
            cs51 = (1.0_wp/2.0_wp)*cs0*inv_Z*s_3*ws1(1, 1) - cs31*cs50 - cs48*ps1(1, 1)
            cs52 = cs1*cs14
            cs53 = cs1*cs23
            cs54 = cs16*cs25
            cs55 = cs26*cs40 + cs31*cs54 - cs52*ws1(1, 1) - cs53*ps1(1, 1) + cs7*ws1(1, 2)
            cs56 = cs13*cs25
            cs57 = 2.0_wp*cs0*cs24*(inv_Z*inv_Z*inv_Z)
            cs58 = &
               -cs31*cs57 + cs32*ws1(1, 3) + cs35*ws1(1, 4) - cs38*ws1(1, 2) + cs40*cs49 + &
               cs41*ws1(1, 1) + cs44*cs45 - cs56*ps1(1, 1)
            cs59 = &
               at2(1, 2, 1)*cs43 + at2(1, 2, 2)*cs37 + at2(1, 2, 3)*cs29 + at2(1, 2, 4)*cs34 - &
               1.0_wp/6.0_wp*aw2(1, 2, 1)*cs0*cs18*inv_Z*s_3 + aw2(1, 2, 2)*cs10 - aw2(1, 2, &
               3)*cs0*cs11*inv_Z - aw2(1, 2, 4)*cs0*inv_Z*ps0(4)*s_2
            cs60 = &
               at2(1, 3, 1)*cs43 + at2(1, 3, 2)*cs37 + at2(1, 3, 3)*cs29 + at2(1, 3, 4)*cs34 - &
               1.0_wp/6.0_wp*aw2(1, 3, 1)*cs0*cs18*inv_Z*s_3 + aw2(1, 3, 2)*cs10 - aw2(1, 3, &
               3)*cs0*cs11*inv_Z - aw2(1, 3, 4)*cs0*inv_Z*ps0(4)*s_2
            cs61 = cs6*ps1(2, 2)
            cs62 = cs14*ps1(2, 1) - cs61
            cs63 = cs11*ps1(2, 3) + cs20*ps1(2, 1) + cs4*ps1(2, 4) - cs61*ps0(1)
            cs64 = cs26*cs62 - cs52*ws1(2, 1) - cs53*ps1(2, 1) + cs54*cs63 + cs7*ws1(2, 2)
            cs65 = (1.0_wp/2.0_wp)*cs0*inv_Z*s_3*ws1(2, 1) - cs48*ps1(2, 1) - cs50*cs63
            cs66 = cs26*s_2
            cs67 = -cs2*ws1(2, 4) + cs46*cs63 + cs66*ps1(2, 4)
            cs68 = -cs1*cs62 + cs41*cs63
            cs69 = (1.0_wp/2.0_wp)*cs0*inv_Z*ps1(2, 1)*s_3 - cs38*cs63
            cs70 = -cs2*ps1(2, 4) + cs35*cs63
            cs71 = &
               cs32*ws1(2, 3) + cs35*ws1(2, 4) - cs38*ws1(2, 2) + cs41*ws1(2, 1) + cs46*ps1(2, 4) &
               + cs49*cs62 - cs56*ps1(2, 1) - cs57*cs63
            cs72 = cs32*cs63
            cs73 = &
               at2(2, 3, 1)*cs43 + at2(2, 3, 2)*cs37 + at2(2, 3, 3)*cs29 + at2(2, 3, 4)*cs34 - &
               1.0_wp/6.0_wp*aw2(2, 3, 1)*cs0*cs18*inv_Z*s_3 + aw2(2, 3, 2)*cs10 - aw2(2, 3, &
               3)*cs0*cs11*inv_Z - aw2(2, 3, 4)*cs0*inv_Z*ps0(4)*s_2
            cs74 = cs6*ps1(3, 2)
            cs75 = cs14*ps1(3, 1) - cs74
            cs76 = cs11*ps1(3, 3) + cs20*ps1(3, 1) + cs4*ps1(3, 4) - cs74*ps0(1)
            cs77 = cs26*cs75 - cs52*ws1(3, 1) - cs53*ps1(3, 1) + cs54*cs76 + cs7*ws1(3, 2)
            cs78 = (1.0_wp/2.0_wp)*cs0*inv_Z*s_3*ws1(3, 1) - cs48*ps1(3, 1) - cs50*cs76
            cs79 = -cs2*ws1(3, 4) + cs46*cs76 + cs66*ps1(3, 4)
            cs80 = -cs1*cs75 + cs41*cs76
            cs81 = (1.0_wp/2.0_wp)*cs0*inv_Z*ps1(3, 1)*s_3 - cs38*cs76
            cs82 = -cs2*ps1(3, 4) + cs35*cs76
            cs83 = &
               cs32*ws1(3, 3) + cs35*ws1(3, 4) - cs38*ws1(3, 2) + cs41*ws1(3, 1) + cs46*ps1(3, 4) &
               + cs49*cs75 - cs56*ps1(3, 1) - cs57*cs76
            cs84 = cs32*cs76
            hvp_f1_rA(1) = &
               at1(1, 1)*cs17 - at1(1, 2)*cs8 + at1(1, 4)*cs3 + aw1(1, 1)*cs21 - aw1(1, 2)*cs10 + &
               aw1(1, 3)*cs12 + aw1(1, 4)*cs5 + cs22*cs26
            hvp_f1_rA(2) = &
               at1(2, 1)*cs17 - at1(2, 2)*cs8 + at1(2, 4)*cs3 + aw1(2, 1)*cs21 - aw1(2, 2)*cs10 + &
               aw1(2, 3)*cs12 + aw1(2, 4)*cs5 + cs26*cs27
            hvp_f1_rA(3) = &
               at1(3, 1)*cs17 - at1(3, 2)*cs8 + at1(3, 4)*cs3 + aw1(3, 1)*cs21 - aw1(3, 2)*cs10 + &
               aw1(3, 3)*cs12 + aw1(3, 4)*cs5 + cs26*cs28
