            t_hvp_f3_rr_rA_020 = &
               -at1(1, 1)*cs351 - at2(1, 1, 1)*cs355 - at2(1, 3, 1)*cs258 - at1(1, 2)*cs364 - &
               at2(1, 1, 2)*cs369 - at2(1, 3, 2)*cs288 - at2(1, 1, 3)*cs372 - at2(1, 3, 3)*cs296 - &
               at1(1, 4)*cs380 - at2(1, 1, 4)*cs384 - at2(1, 3, 4)*cs318 - aw1(1, 1)*cs385 - &
               aw2(1, 1, 1)*cs387 - aw2(1, 3, 1)*cs50 - aw1(1, 2)*cs388 - aw2(1, 1, 2)*cs119 - &
               aw2(1, 3, 2)*cs46 - aw1(1, 3)*cs392 - aw2(1, 1, 3)*cs129 - aw2(1, 3, 3)*cs38 - &
               aw1(1, 4)*cs389 - aw2(1, 1, 4)*cs122 - aw2(1, 3, 4)*cs44 - cs223 + cs26*cs391
            hvp_f3_rr_rA(1, 3, 1) = t_hvp_f3_rr_rA_020
            hvp_f3_rr_rA(3, 1, 1) = t_hvp_f3_rr_rA_020
            t_hvp_f3_rr_rA_021 = &
               -at1(2, 1)*cs351 - at1(2, 2)*cs364 - at1(2, 4)*cs380 - aw1(2, 1)*cs385 - aw1(2, &
               2)*cs388 - aw1(2, 3)*cs392 - aw1(2, 4)*cs389 + cs31*cs391 - cs329 - cs330 - cs331 - &
               cs332 - cs333 - cs334 - cs335 - cs336 - cs338 - cs393
            hvp_f3_rr_rA(1, 3, 2) = t_hvp_f3_rr_rA_021
            hvp_f3_rr_rA(3, 1, 2) = t_hvp_f3_rr_rA_021
            t_hvp_f3_rr_rA_022 = &
               -at2(1, 3, 1)*cs355 - at1(3, 1)*cs351 - at2(3, 3, 1)*cs258 - at2(1, 3, 2)*cs369 - &
               at1(3, 2)*cs364 - at2(3, 3, 2)*cs288 - at2(1, 3, 3)*cs372 - at2(3, 3, 3)*cs296 - &
               at2(1, 3, 4)*cs384 - at1(3, 4)*cs380 - at2(3, 3, 4)*cs318 - aw2(1, 3, 1)*cs387 - &
               aw1(3, 1)*cs385 - aw2(3, 3, 1)*cs50 - aw2(1, 3, 2)*cs119 - aw1(3, 2)*cs388 - aw2(3, &
               3, 2)*cs46 - aw2(1, 3, 3)*cs129 - aw1(3, 3)*cs392 - aw2(3, 3, 3)*cs38 - aw2(1, 3, &
               4)*cs122 - aw1(3, 4)*cs389 - aw2(3, 3, 4)*cs44 + cs32*cs391 - cs394
            hvp_f3_rr_rA(1, 3, 3) = t_hvp_f3_rr_rA_022
            hvp_f3_rr_rA(3, 1, 3) = t_hvp_f3_rr_rA_022
            hvp_f3_rr_rA(2, 2, 1) = &
               -at1(1, 1)*cs408 - at2(1, 2, 1)*cs414 - at1(1, 2)*cs416 - at2(1, 2, 2)*cs418 - &
               at2(1, 2, 3)*cs421 - at1(1, 4)*cs428 - at2(1, 2, 4)*cs430 - aw1(1, 1)*cs431 - &
               aw2(1, 2, 1)*cs432 - aw1(1, 2)*cs433 - aw2(1, 2, 2)*cs434 - aw1(1, 3)*cs439 - &
               aw2(1, 2, 3)*cs440 - aw1(1, 4)*cs435 - aw2(1, 2, 4)*cs436 + cs26*cs438 - cs328
            hvp_f3_rr_rA(2, 2, 2) = &
               -at1(2, 1)*cs408 - at2(2, 2, 1)*cs414 - at3(2, 2, 2, 1)*cs51 - at1(2, 2)*cs416 - &
               at2(2, 2, 2)*cs418 - at3(2, 2, 2, 2)*cs45 - at2(2, 2, 3)*cs421 - at3(2, 2, 2, &
               3)*cs33 - at1(2, 4)*cs428 - at2(2, 2, 4)*cs430 - at3(2, 2, 2, 4)*cs39 - aw1(2, &
               1)*cs431 - aw2(2, 2, 1)*cs432 + (1.0_wp/6.0_wp)*aw3(2, 2, 2, 1)*cs0*cs22*inv_Z*s_3 &
               - aw1(2, 2)*cs433 - aw2(2, 2, 2)*cs434 - aw3(2, 2, 2, 2)*cs10 - aw1(2, 3)*cs439 - &
               aw2(2, 2, 3)*cs440 + aw3(2, 2, 2, 3)*cs0*cs13*inv_Z - aw1(2, 4)*cs435 - aw2(2, 2, &
               4)*cs436 + aw3(2, 2, 2, 4)*cs0*inv_Z*ps0(4)*s_2 + cs31*cs438
            hvp_f3_rr_rA(2, 2, 3) = &
               -at2(2, 3, 1)*cs414 - at1(3, 1)*cs408 - at2(2, 3, 2)*cs418 - at1(3, 2)*cs416 - &
               at2(2, 3, 3)*cs421 - at2(2, 3, 4)*cs430 - at1(3, 4)*cs428 - aw2(2, 3, 1)*cs432 - &
               aw1(3, 1)*cs431 - aw2(2, 3, 2)*cs434 - aw1(3, 2)*cs433 - aw2(2, 3, 3)*cs440 - &
               aw1(3, 3)*cs439 - aw2(2, 3, 4)*cs436 - aw1(3, 4)*cs435 + cs32*cs438 - cs441
            t_hvp_f3_rr_rA_120 = &
               -at1(1, 1)*cs447 - at2(1, 3, 1)*cs449 - at1(1, 2)*cs454 - at1(1, 4)*cs457 - aw1(1, &
               1)*cs458 - aw2(1, 3, 1)*cs92 - aw1(1, 2)*cs459 - aw1(1, 3)*cs462 - aw1(1, 4)*cs460 &
               + cs26*cs461 - cs337 - cs393
            hvp_f3_rr_rA(2, 3, 1) = t_hvp_f3_rr_rA_120
            hvp_f3_rr_rA(3, 2, 1) = t_hvp_f3_rr_rA_120
            t_hvp_f3_rr_rA_121 = &
               -at1(2, 1)*cs447 - at2(2, 2, 1)*cs355 - at2(2, 3, 1)*cs449 - at1(2, 2)*cs454 - &
               at2(2, 2, 2)*cs369 - at2(2, 3, 2)*cs286 - at2(2, 2, 3)*cs372 - at2(2, 3, 3)*cs295 - &
               at1(2, 4)*cs457 - at2(2, 2, 4)*cs384 - at2(2, 3, 4)*cs316 - aw1(2, 1)*cs458 - &
               aw2(2, 2, 1)*cs387 - aw2(2, 3, 1)*cs92 - aw1(2, 2)*cs459 - aw2(2, 2, 2)*cs119 - &
               aw2(2, 3, 2)*cs93 - aw1(2, 3)*cs462 - aw2(2, 2, 3)*cs129 - aw2(2, 3, 3)*cs103 - &
               aw1(2, 4)*cs460 - aw2(2, 2, 4)*cs122 - aw2(2, 3, 4)*cs96 + cs31*cs461 - cs441
            hvp_f3_rr_rA(2, 3, 2) = t_hvp_f3_rr_rA_121
            hvp_f3_rr_rA(3, 2, 2) = t_hvp_f3_rr_rA_121
            t_hvp_f3_rr_rA_122 = &
               -at2(2, 3, 1)*cs355 - at1(3, 1)*cs447 - at2(3, 3, 1)*cs449 - at2(2, 3, 2)*cs369 - &
               at1(3, 2)*cs454 - at2(3, 3, 2)*cs286 - at2(2, 3, 3)*cs372 - at2(3, 3, 3)*cs295 - &
               at2(2, 3, 4)*cs384 - at1(3, 4)*cs457 - at2(3, 3, 4)*cs316 - aw2(2, 3, 1)*cs387 - &
               aw1(3, 1)*cs458 - aw2(3, 3, 1)*cs92 - aw2(2, 3, 2)*cs119 - aw1(3, 2)*cs459 - aw2(3, &
               3, 2)*cs93 - aw2(2, 3, 3)*cs129 - aw1(3, 3)*cs462 - aw2(3, 3, 3)*cs103 - aw2(2, 3, &
               4)*cs122 - aw1(3, 4)*cs460 - aw2(3, 3, 4)*cs96 + cs32*cs461 - cs463
            hvp_f3_rr_rA(2, 3, 3) = t_hvp_f3_rr_rA_122
            hvp_f3_rr_rA(3, 2, 3) = t_hvp_f3_rr_rA_122
            hvp_f3_rr_rA(3, 3, 1) = &
               -at1(1, 1)*cs477 - at2(1, 3, 1)*cs481 - at1(1, 2)*cs484 - at2(1, 3, 2)*cs486 - &
               at2(1, 3, 3)*cs487 - at1(1, 4)*cs494 - at2(1, 3, 4)*cs496 - aw1(1, 1)*cs497 - &
               aw2(1, 3, 1)*cs498 - aw1(1, 2)*cs499 - aw2(1, 3, 2)*cs500 - aw1(1, 3)*cs504 - &
               aw2(1, 3, 3)*cs505 - aw1(1, 4)*cs501 - aw2(1, 3, 4)*cs502 + cs26*cs503 - cs394
            hvp_f3_rr_rA(3, 3, 2) = &
               -at1(2, 1)*cs477 - at2(2, 3, 1)*cs481 - at1(2, 2)*cs484 - at2(2, 3, 2)*cs486 - &
               at2(2, 3, 3)*cs487 - at1(2, 4)*cs494 - at2(2, 3, 4)*cs496 - aw1(2, 1)*cs497 - &
               aw2(2, 3, 1)*cs498 - aw1(2, 2)*cs499 - aw2(2, 3, 2)*cs500 - aw1(2, 3)*cs504 - &
               aw2(2, 3, 3)*cs505 - aw1(2, 4)*cs501 - aw2(2, 3, 4)*cs502 + cs31*cs503 - cs463
            hvp_f3_rr_rA(3, 3, 3) = &
               -at1(3, 1)*cs477 - at2(3, 3, 1)*cs481 - at3(3, 3, 3, 1)*cs51 - at1(3, 2)*cs484 - &
               at2(3, 3, 2)*cs486 - at3(3, 3, 3, 2)*cs45 - at2(3, 3, 3)*cs487 - at3(3, 3, 3, &
               3)*cs33 - at1(3, 4)*cs494 - at2(3, 3, 4)*cs496 - at3(3, 3, 3, 4)*cs39 - aw1(3, &
               1)*cs497 - aw2(3, 3, 1)*cs498 + (1.0_wp/6.0_wp)*aw3(3, 3, 3, 1)*cs0*cs22*inv_Z*s_3 &
               - aw1(3, 2)*cs499 - aw2(3, 3, 2)*cs500 - aw3(3, 3, 3, 2)*cs10 - aw1(3, 3)*cs504 - &
               aw2(3, 3, 3)*cs505 + aw3(3, 3, 3, 3)*cs0*cs13*inv_Z - aw1(3, 4)*cs501 - aw2(3, 3, &
               4)*cs502 + aw3(3, 3, 3, 4)*cs0*inv_Z*ps0(4)*s_2 + cs32*cs503
         end block
      end select

   end subroutine svdw_hvp_eval

   !> Joint-direction Hessian-vector product with a retained *radius* derivative.
   !>
   !> Returns `sum_B (v_B . d/dR_B + vr_B d/dR_b) d/dR_a d^n S / dr^n` for
   !> n = 0..max_deriv, i.e. `hvp_f1_rad`, `hvp_f2_r_rad` and `hvp_f3_rr_rad`,
   !> where `R_a` is the radius of atom A.  The results carry no trailing index:
   !> the rank is the spatial order.
   !>
   !> This is the radius row of the cavity Hessian.  With `R = R(X)` the chain
   !> rule needs four blocks -- nuclear-nuclear, nuclear-radius, radius-nuclear
   !> and radius-radius -- and this routine supplies the two that retain a radius
   !> index, because the contraction direction is the joint pair `(v_B, vr_B)`.
   !> `svdw_hvp_eval` supplies the other two from the same `ws` inputs.
   !>
   !> The radius-radius coupling between *different* atoms is nonzero and is not
   !> recoverable from per-atom data: `at`/`aw` carry no `R_b` dependence, so all
   !> of it comes from the nonlinearity of Z in the power sums and from the log,
   !> exactly as for `f2_rArB`.
   !>
   !> Results above `max_deriv` are left untouched.
   !>
   !> @param[in]    blend_k      Blending sharpness k of u = exp(-(k/3) d)
   !> @param[in]    s_1          One-body blending weight blend_1b
   !> @param[in]    s_2          Two-body blending weight blend_2b
   !> @param[in]    s_3          Three-body blending weight blend_3b
   !> @param[in]    ps0          Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps1          Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ps2          Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all
   !>                            active atoms; last index selects the kind (1 = p1, 2 = p2, 3 = p3,
   !>                            4 = q)
   !> @param[in]    ws0          Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the
   !>                            order-0 power-sum tensor; last index selects the kind
   !> @param[in]    ws1          Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the
   !>                            order-1 power-sum tensor; last index selects the kind
   !> @param[in]    ws2          Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the
   !>                            order-2 power-sum tensor; last index selects the kind
   !> @param[in]    at0          Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at1          Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    at2          Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index
   !>                            selects the kind
   !> @param[in]    aw0          Atom-A direction-contracted kind tensor from
   !>                            svdw_atom_tangent_eval; last index selects the kind
   !> @param[in]    aw1          Atom-A direction-contracted kind tensor from
   !>                            svdw_atom_tangent_eval; last index selects the kind
   !> @param[in]    aw2          Atom-A direction-contracted kind tensor from
   !>                            svdw_atom_tangent_eval; last index selects the kind
   !> @param[in]    max_deriv    Highest spatial-derivative order to compute (0..2); a larger value
   !>                            is treated as 2
   !> @param[out]   hvp_f1_rad   sum_B v_B . d^2S/(dR_a dR_B) + sum_B vr_B d^2S/(dR_a dR_b)
   !> @param[out]   hvp_f2_r_rad the same for dS/dr
   !> @param[out]   hvp_f3_rr_rad the same for d^2S/dr^2
   pure subroutine svdw_radius_hvp_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, ws0, ws1, ws2, &
                                        at0, at1, at2, aw0, aw1, aw2, max_deriv, hvp_f1_rad, &
                                        hvp_f2_r_rad, hvp_f3_rr_rad)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the order-0 power-sum tensor;
      !> last index selects the kind
      real(wp), intent(in) :: ws0(nkind)
      !> Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the order-1 power-sum tensor;
      !> last index selects the kind
      real(wp), intent(in) :: ws1(3, nkind)
      !> Accumulated direction-contracted tensor sum_B v_B . d/dR_B of the order-2 power-sum tensor;
      !> last index selects the kind
      real(wp), intent(in) :: ws2(3, 3, nkind)
      !> Atom-A kind tensor d^0 u_A^m / dr^0 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at0(nkind)
      !> Atom-A kind tensor d^1 u_A^m / dr^1 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at1(3, nkind)
      !> Atom-A kind tensor d^2 u_A^m / dr^2 from svdw_atom_eval; last index selects the kind
      real(wp), intent(in) :: at2(3, 3, nkind)
      !> Atom-A direction-contracted kind tensor from svdw_atom_tangent_eval; last index selects the
      !> kind
      real(wp), intent(in) :: aw0(nkind)
      !> Atom-A direction-contracted kind tensor from svdw_atom_tangent_eval; last index selects the
      !> kind
      real(wp), intent(in) :: aw1(3, nkind)
      !> Atom-A direction-contracted kind tensor from svdw_atom_tangent_eval; last index selects the
      !> kind
      real(wp), intent(in) :: aw2(3, 3, nkind)
      !> Highest spatial-derivative order to compute (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> sum_B v_B . d^2S/(dR_a dR_B) + sum_B vr_B d^2S/(dR_a dR_b)
      real(wp), intent(out) :: hvp_f1_rad
      !> the same for dS/dr
      real(wp), intent(out) :: hvp_f2_r_rad(3)
      !> the same for d^2S/dr^2
      real(wp), intent(out) :: hvp_f3_rr_rad(3, 3)

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7

            cs0 = (1.0_wp/2.0_wp)*s_2
            cs1 = at0(4)*cs0
            cs2 = (1.0_wp/3.0_wp)*s_3
            cs3 = -cs0 + cs2 + s_1
            cs4 = (1.0_wp/2.0_wp)*s_3*ws0(2)
            cs5 = s_3*ws0(1)
            cs6 = 3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2)
            cs7 = (1.0_wp/18.0_wp)*cs6*s_3
            hvp_f1_rad = &
               -1.0_wp/3.0_wp*at0(1)*inv_Z*(-cs4 + cs5*ps0(1)) + &
               (1.0_wp/3.0_wp)*at0(2)*inv_Z*s_3*ws0(1) - aw0(1)*cs7*inv_Z + &
               (1.0_wp/3.0_wp)*aw0(2)*inv_Z*ps0(1)*s_3 - aw0(3)*cs3*inv_Z - &
               aw0(4)*cs0*inv_Z*ps0(4) - cs1*inv_Z*ws0(4) + (inv_Z*inv_Z)*(cs3*ws0(3) - cs4*ps0(1) &
               + (1.0_wp/6.0_wp)*cs5*cs6 + ps0(4)*s_2*ws0(4))*(at0(1)*blend_k*cs7 - &
               at0(2)*blend_k*cs2*ps0(1) + at0(3)*blend_k*cs3 + blend_k*cs1*ps0(4))/blend_k
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65
            real(wp) :: cs66, cs67

            cs0 = (1.0_wp/2.0_wp)*s_2
            cs1 = at0(4)*cs0
            cs2 = cs0*inv_Z*ps0(4)
            cs3 = (1.0_wp/3.0_wp)*s_3
            cs4 = -cs0 + cs3 + s_1
            cs5 = cs4*inv_Z
            cs6 = (1.0_wp/2.0_wp)*s_3
            cs7 = cs6*ws0(2)
            cs8 = ps0(1)*s_3
            cs9 = cs8*ws0(1)
            cs10 = -cs7 + cs9
            cs11 = (1.0_wp/3.0_wp)*at0(1)
            cs12 = s_3*(3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2))
            cs13 = (1.0_wp/18.0_wp)*cs12
            cs14 = cs13*inv_Z
            cs15 = 1.0_wp/blend_k
            cs16 = (inv_Z*inv_Z)
            cs17 = ps0(4)*s_2
            cs18 = (1.0_wp/6.0_wp)*cs12
            cs19 = cs17*ws0(4) + cs18*ws0(1) + cs4*ws0(3) - cs7*ps0(1)
            cs20 = &
               at0(1)*blend_k*cs13 - at0(2)*blend_k*cs3*ps0(1) + at0(3)*blend_k*cs4 + &
               blend_k*cs1*ps0(4)
            cs21 = cs3*inv_Z*ps0(1)
            cs22 = cs16*cs4
            cs23 = cs19*cs22
            cs24 = cs6*ps1(1, 2)
            cs25 = cs17*ps1(1, 4) + cs18*ps1(1, 1) - cs24*ps0(1) + cs4*ps1(1, 3)
            cs26 = aw0(3)*cs22
            cs27 = cs15*inv_Z
            cs28 = cs27*s_2
            cs29 = cs15*cs16
            cs30 = cs19*cs29
            cs31 = (1.0_wp/2.0_wp)*blend_k
            cs32 = cs31*(cs17*cs30 - cs28*ws0(4))
            cs33 = cs17*cs29
            cs34 = aw0(4)*cs31
            cs35 = cs6*ps0(1)
            cs36 = (2.0_wp/3.0_wp)*blend_k
            cs37 = cs36*((1.0_wp/2.0_wp)*cs15*inv_Z*s_3*ws0(1) - cs30*cs35)
            cs38 = cs29*cs35
            cs39 = aw0(2)*cs36
            cs40 = -cs24 + cs8*ps1(1, 1)
            cs41 = cs18*cs29
            cs42 = (1.0_wp/3.0_wp)*blend_k
            cs43 = aw0(1)*cs42
            cs44 = cs42*(cs18*cs30 + cs27*cs7 - cs27*cs9)
            cs45 = ps1(1, 4)*s_2
            cs46 = cs29*ws0(4)
            cs47 = cs46*s_2
